1	/**
2	 * The world source that asks the engine, and draws the answers it gets back.
3	 *
4	 * This is where the two halves of the product meet. The canvas was written
5	 * against `WorldSource` and nothing else, so joining it to the engine changed no
6	 * component: the object handed in changed, the slots that used to read *no
7	 * engine yet* now hold computed numbers, and every absence that is still on
8	 * screen is still an absence for a reason it can name.
9	 *
10	 * **Three questions, three routes, and nothing else is asked.**
11	 *
12	 * | The question | Where it is asked |
13	 * |---|---|
14	 * | What does this branch make the map say? | `POST /api/worlds` |
15	 * | What moved between the map as written and the map with my edits? | `POST /api/worlds/diff` |
16	 * | What is the number on this one arrow? | `POST /api/worlds/conditional` |
17	 *
18	 * A fourth thing is read and is not the engine's: the map itself — the claims,
19	 * their wording, how each is judged, the arrows and what is cited for them —
20	 * which comes from the stored-example route. A map is written by hand; a world
21	 * never is. So the map is read once and kept, and the engine is asked again
22	 * every time an edit lands.
23	 *
24	 * **There is no arithmetic on a likelihood anywhere in this file.** Numbers
25	 * arrive from the engine and are carried, untouched and at full precision, to
26	 * the moment they are printed. Which way a claim moved is read off the sign of
27	 * the engine's own difference — a comparison, not a subtraction — and no two
28	 * numbers on this map are ever combined here.
29	 *
30	 * **Nothing here is invented.** A branch that does not fit comes back as every
31	 * reason at once and is thrown on for the screen to print. A claim under a live
32	 * supposition gets the word rather than the `1` the engine stores for it. And a
33	 * chain's multiplied-out likelihood, which the engine does not carry, stays an
34	 * absence that says exactly that rather than being worked out here.
35	 */
36	
37	import type { ClaimDiff, Diff, World } from "../api/client";
38	import { readConditional, readDiff, readExample, readWorld } from "../api/client";
39	import { ADDED, happened, retracted, supposed } from "../graph/diff/badges";
40	import { daysApart } from "../graph/diff/days";
41	import { filled, NO_PATH_PRODUCT, seedFor, toClaim, toLink } from "./fromTheServer";
42	import type { FixtureBundle, WorldSource } from "./source";
43	import type {
44	  Badge,
45	  BranchView,
46	  ClaimChange,
47	  ClaimView,
48	  ConditionalRequest,
49	  DeltaRow,
50	  DiffRequest,
51	  DiffView,
52	  Known,
53	  Movement,
54	  Ranged,
55	  Standing,
56	  WireBranch,
57	  WorldRequest,
58	  WorldView,
59	} from "./types";
60	
61	/**
62	 * Which likelihood on a claim's series is the one its tile shows.
63	 *
64	 * A tile's headline number is read on the claim's **own resolve-by day** — the
65	 * day the claim is judged, which every claim has and which the tile already
66	 * prints. So the word beside that number has to be read on the same day, or the
67	 * tile would say *Supposed* over a number worked out for a different morning.
68	 *
69	 * @param world The world as the engine built it.
70	 * @param resolvesBy The claim's own resolve-by day.
71	 * @returns Where that day sits among the days the world was worked through, or
72	 *   nothing at all when the day is outside the window or was not one of the days
73	 *   drawn.
74	 */
75	function whereItsDaySits(world: World, resolvesBy: string): number | null {
76	  const day = daysApart(world.day_zero, resolvesBy);
77	  if (day === null) {
78	    return null;
79	  }
80	  const at = world.series_days.indexOf(day);
81	  return at === -1 ? null : at;
82	}
83	
84	/**
85	 * What a tile says about the edits behind it, read off the world rather than
86	 * worked out from the branch.
87	 *
88	 * The world carries both halves: every value an edit fixed, in the order the
89	 * edits were made, and every supposition a later edit undermined with the day
90	 * and the arrow that did it. Reading the badges off those is what closes the
91	 * question the diff chapter left open — two derivations of one line eventually
92	 * disagree, so there is one, and it is the world's.
93	 *
94	 * One badge is not on the world and cannot be: **Added**. Whether a claim
95	 * arrived with an edit is a fact about the branch, and the branch is what says
96	 * so — the world only shows the map the edits left behind, in which an added
97	 * claim looks like any other.
98	 *
99	 * @param world The world as the engine built it.
100	 * @param words Every claim's own words, so a badge can quote one.
101	 * @param added The claims this branch brought with it.
102	 * @returns One list of badges per claim that has any, in the order they were
103	 *   earned.
104	 */
105	function badgesFromTheWorld(
106	  world: World,
107	  words: ReadonlyMap<string, string>,
108	  added: ReadonlySet<string>,
109	): Map<string, Badge[]> {
110	  const badges = new Map<string, Badge[]>();
111	  const add = (claim: string, badge: Badge): void => {
112	    badges.set(claim, [...(badges.get(claim) ?? []), badge]);
113	  };
114	
115	  // A claim an edit brought with it earns **Added** before anything it is later
116	  // supposed to be: it has to be on the map before anything can be said about
117	  // it, so that is the order the two badges read in.
118	  for (const claim of added) {
119	    add(claim, ADDED);
120	  }
121	
122	  const supposedOn = new Map<string, string>();
123	  for (const fixed of world.assignments) {
124	    const day = fixed.at ?? world.day_zero;
125	    if (fixed.kind === "do") {
126	      add(fixed.target, supposed(day, fixed.value));
127	      if (fixed.value) {
128	        supposedOn.set(fixed.target, day);
129	      }
130	    } else {
131	      add(fixed.target, happened(day));
132	    }
133	  }
134	
135	  for (const end of world.retractions) {
136	    const cause = words.get(end.by_claim) ?? end.by_claim;
137	    add(end.target, retracted(end.at, cause, supposedOn.get(end.target) ?? end.at));
138	  }
139	
140	  return badges;
141	}
142	
143	/**
144	 * Which claims an edit has fixed the value of, on their own judging day.
145	 *
146	 * **One rule, and it is not a rule about suppositions.** A claim whose value an
147	 * edit fixed is true — or false — in every version of the map, so the engine
148	 * stores a flat `1` or `0` for it, and **no surface but the path product prints
149	 * that number.** Every other reader writes the word where the likelihood would
150	 * go: *Supposed · Oct 1* where the reader took it as given, *Happened · Oct 1*
151	 * where they reported it as news. Answering either with a likelihood is a tool
152	 * arguing with the person using it — and `>.99` is that number wearing the
153	 * certainty guard's clothes.
154	 *
155	 * **The two are found in different places, and that is the engine's shape rather
156	 * than ours.** A supposition can be undermined by a later edit, so whether it
157	 * still holds is a fact about a *day*, and the world's `states` carry it — H
158	 * reads *supposed* on the first and *pushed* by the day it is judged. An
159	 * observation is news: nothing takes it back, it holds across the whole window,
160	 * and the world records it as an assignment rather than as a state.
161	 *
162	 * @param world The world as the engine built it.
163	 * @param claims The claims, so each one's resolve-by day can be found.
164	 * @param badges The badges, for the words and the sentence behind them.
165	 */
166	function standingFromTheWorld(
167	  world: World,
168	  claims: readonly ClaimView[],
169	  badges: ReadonlyMap<string, readonly Badge[]>,
170	): Map<string, Standing> {
171	  const observed = new Set(
172	    world.assignments.filter((fixed) => fixed.kind === "observe").map((fixed) => fixed.target),
173	  );
174	  const standing = new Map<string, Standing>();
175	  for (const claim of claims) {
176	    const at = whereItsDaySits(world, claim.resolvesBy);
177	    const isSupposed = at !== null && world.states[claim.id]?.[at] === "supposed";
178	    const isNews = observed.has(claim.id);
179	    if (!isSupposed && !isNews) {
180	      continue;
181	    }
182	    const word = isSupposed ? "Supposed" : "Happened";
183	    const said = (badges.get(claim.id) ?? []).find((badge) => badge.words.startsWith(word));
184	    standing.set(claim.id, {
185	      words: said?.words ?? word,
186	      reason:
187	        `${said?.reason ?? "An edit fixed this claim's value."} It is settled in every version ` +
188	        `of the map, so there is no likelihood to show.`,
189	    });
190	  }
191	  return standing;
192	}
193	
194	/**
195	 * The one sentence under a computed map, saying where every number on it came
196	 * from.
197	 *
198	 * It names both halves — the address the map was read from and the address its
199	 * likelihoods were worked out at — and the three things anyone would need to
200	 * rebuild the same answer: the map, the branch, and the seed.
201	 */
202	function originOf(world: World, bundle: FixtureBundle, branchLabel: string | null): string {
203	  const which =
204	    branchLabel === null
205	      ? "with nothing done to it"
206	      : `with the branch "${branchLabel}" folded onto it`;
207	  return (
208	    `Every claim, arrow and date came from /api/fixtures/${bundle.id}; every likelihood was ` +
209	    `worked out by /api/worlds from that map ${which}, at seed ${world.seed}, over ` +
210	    `${world.versions.toLocaleString("en-GB").replace(/,/g, " ")} versions of the map with ` +
211	    `${world.worlds} worlds under each. Nothing here was typed in: the same map, branch and ` +
212	    `seed give the same answer every time.`
213	  );
214	}
215	
216	/**
217	 * Turn one computed world into the world the canvas draws.
218	 *
219	 * @param world The world as the engine built it.
220	 * @param bundle The stored example, for the map's title and its address.
221	 * @param branch The branch that was folded, or nothing on the base world.
222	 */
223	function toWorldView(world: World, bundle: FixtureBundle, branch?: BranchView): WorldView {
224	  // The map the engine's edits left behind, which is the map to draw: a branch
225	  // that added a claim added it here too.
226	  const claims = world.graph.propositions.map(toClaim);
227	  const words = new Map(claims.map((claim) => [claim.id, claim.claim]));
228	  const added = new Set(
229	    (branch?.edits ?? []).flatMap((edit) => (edit.op === "insert" ? [edit.claimId] : [])),
230	  );
231	  const badges = badgesFromTheWorld(world, words, added);
232	  const standing = standingFromTheWorld(world, claims, badges);
233	
234	  return {
235	    baseId: bundle.id,
236	    title: bundle.title,
237	    today: bundle.fixture_date,
238	    hypothesisId: world.graph.hypothesis_id,
239	    claims: claims.map((claim): ClaimView => {
240	      const computed = world.beliefs[claim.id];
241	      return {
242	        ...claim,
243	        // The engine's own answer for this claim, read on the day the claim is
244	        // judged. It replaces the likelihood the map was written with, and it
245	        // replaces nothing else: the reader's own number and a venue's price
246	        // are theirs.
247	        beliefs: {
248	          ...claim.beliefs,
249	          model: computed === undefined ? claim.beliefs.model : filled(computed),
250	        },
251	        badges: badges.get(claim.id) ?? [],
252	        standing: standing.get(claim.id),
253	        // A chain's multiplied-out likelihood is not on a world, so it stays an
254	        // absence that says so. Nothing here multiplies one.
255	        pathProduct: { absence: NO_PATH_PRODUCT },
256	      };
257	    }),
258	    links: world.graph.links.map(toLink),
259	    versions: world.versions,
260	    worldsPerVersion: world.worlds,
261	    seed: world.seed,
262	    warnings: world.warnings,
263	    origin: originOf(world, bundle, branch?.label ?? null),
264	  };
265	}
266	
267	/**
268	 * How far one claim moved, as the engine read it.
269	 *
270	 * Every part of it is the engine's own: the two readings, the sign that says
271	 * which way it went, the share of versions that agreed, and whether the move
272	 * came from nothing but the observation changing how much each version counts.
273	 * Nothing here subtracts, compares two numbers, or works anything out.
274	 *
275	 * @param row The claim's own row of the engine's difference.
276	 */
277	function movement(row: ClaimDiff): Movement | undefined {
278	  const { before, after, delta, agreement } = row;
279	  if (before === null || after === null || delta === null) {
280	    return undefined;
281	  }
282	  return {
283	    from: before,
284	    to: after,
285	    // Which way it went is the sign of the engine's own difference. Reading a
286	    // sign is a comparison against nought, not a subtraction: nothing here works
287	    // out how far anything moved.
288	    way: delta < 0 ? "down" : "up",
289	    by: delta,
290	    sameDirection:
291	      agreement === null
292	        ? {
293	            absence: {
294	              kind: "no_engine",
295	              words: "—",
296	              reason:
297	                "Only one of the two worlds holds this claim, so there is no direction for the " +
298	                "versions of the map to have agreed or disagreed about.",
299	            },
300	          }
301	        : { reading: agreement },
302	    // A claim with no causes of its own can move under **This happened** without
303	    // anything pushing on it: the observation makes the versions of the map in
304	    // which it was likely count for more, and the average shifts. The engine
305	    // says when that is the whole story, and the panel prints one sentence when
306	    // it does. **The browser never works this out for itself** — it is a fact
307	    // about how the engine read the numbers, and only the engine knows it.
308	    onlyReweighted: row.moved_only_by_reweighting,
309	  };
310	}
311	
312	/** Turn the engine's difference into what the rail and the tiles read. */
313	function toDiffView(difference: Diff, claims: readonly ClaimView[]): DiffView {
314	  const byId = new Map(claims.map((claim) => [claim.id, claim]));
315	
316	  const changed = new Map<string, ClaimChange>();
317	  for (const [id, one] of Object.entries(difference.claims)) {
318	    changed.set(id, {
319	      state: one.state,
320	      moved: movement(one),
321	    });
322	  }
323	
324	  // The endings that moved, in the engine's own order, largest rank first.
325	  // Nothing here sorts, re-ranks or drops a row.
326	  const ranked: DeltaRow[] = difference.rows.map((row): DeltaRow => {
327	    const claim = byId.get(row.target);
328	    return {
329	      claimId: row.target,
330	      label: claim?.claim ?? row.target,
331	      kind: claim?.kind ?? "market",
332	      move: {
333	        reading: {
334	          from: row.before,
335	          to: row.after,
336	          largestOn: row.at_day,
337	          way: row.peak_delta < 0 ? "down" : "up",
338	          by: row.peak_delta,
339	        },
340	      },
341	      rangeWidth: { reading: row.range_width },
342	      agreement: { reading: row.agreement },
343	    };
344	  });
345	
346	  // An ending the engine left off that list did not move. Silence cannot be
347	  // told from absence — a reader would not know whether the ending held still
348	  // or is simply not on this map — so it gets a quiet row of its own, after
349	  // every ranked row and never mixed in among them.
350	  const listed = new Set(ranked.map((row) => row.claimId));
351	  const held: DeltaRow[] = claims
352	    .filter(
353	      (claim) =>
354	        (claim.kind === "market" || claim.kind === "not_tradeable") &&
355	        !listed.has(claim.id) &&
356	        changed.get(claim.id)?.state === "unchanged",
357	    )
358	    .map((claim) => ({
359	      claimId: claim.id,
360	      label: claim.claim,
361	      kind: claim.kind,
362	      move: {
363	        absence: {
364	          kind: "no_engine" as const,
365	          words: "no change",
366	          reason:
367	            "This ending is on the map and your edit did not move it: the engine compared the " +
368	            "two worlds and found no move worth reporting. It is listed so that holding still " +
369	            "cannot be mistaken for not being here.",
370	        },
371	      },
372	      rangeWidth: {
373	        absence: {
374	          kind: "no_engine" as const,
375	          words: "—",
376	          reason: "How firm a number is only says something about a number that moved.",
377	        },
378	      },
379	      agreement: {
380	        absence: {
381	          kind: "no_engine" as const,
382	          words: "—",
383	          reason:
384	            "Whether the versions of the map agreed on a direction only says something about a " +
385	            "claim that had a direction.",
386	        },
387	      },
388	      noChange: true,
389	    }));
390	
391	  const summary: Known<string> = { reading: difference.summary };
392	  return { claims: changed, rows: [...ranked, ...held], summary, warnings: difference.warnings };
393	}
394	
395	/**
396	 * The branch in the shape that goes over the wire, or a sentence saying why it
397	 * cannot go.
398	 *
399	 * A branch is only askable about when every edit in it can be written down the
400	 * way the server writes one. Today one edit cannot: a claim of your own needs
401	 * the part of this product that drafts a whole claim — its wording, how it is
402	 * judged, by whom, by when — and that is not connected.
403	 *
404	 * @param branch The branch the screen is showing.
405	 * @throws Error With one plain sentence, when the branch cannot be sent.
406	 */
407	function sendable(branch: BranchView): WireBranch {
408	  if (branch.wire === undefined) {
409	    throw new Error(
410	      `The branch "${branch.label}" has an edit this build cannot hand to the engine, so no ` +
411	        `world was asked for. Adding a claim of your own needs the part of this product that ` +
412	        `drafts one, and that is not connected yet.`,
413	    );
414	  }
415	  return branch.wire;
416	}
417	
418	/**
419	 * Calls the engine for a computed world, for what an edit moved, and for the
420	 * number on one arrow.
421	 *
422	 * It keeps one thing between calls: the stored example itself, because a map is
423	 * written by hand and does not change while the page is open. It keeps no
424	 * world, no difference and no likelihood — those are computed results, and a
425	 * kept one eventually disagrees with the three things it came from.
426	 */
427	export class ApiWorldSource implements WorldSource {
428	  /** The stored examples this page has already read, by their short names. */
429	  readonly #maps = new Map<string, Promise<FixtureBundle>>();
430	
431	  /** The base map and its branches, read once and kept for as long as the page is open. */
432	  async readBundle(id: string): Promise<FixtureBundle> {
433	    const already = this.#maps.get(id);
434	    if (already !== undefined) {
435	      return already;
436	    }
437	    const asked = readExample(id);
438	    this.#maps.set(id, asked);
439	    try {
440	      return await asked;
441	    } catch (failure) {
442	      // A map that could not be read is not a map we should go on pretending to
443	      // have. Forgetting it means the next attempt really asks again.
444	      this.#maps.delete(id);
445	      throw failure;
446	    }
447	  }
448	
449	  /**
450	   * One computed world: the map with this branch folded onto it and every
451	   * likelihood worked through time.
452	   *
453	   * @param request Which map, and which branch — sent whole, because there is
454	   *   nowhere to keep one yet.
455	   */
456	  async readWorld(request: WorldRequest): Promise<WorldView> {
457	    const bundle = await this.readBundle(request.baseId);
458	    const branch = request.branch;
459	    const world = await readWorld(
460	      request.baseId,
461	      branch === undefined ? null : sendable(branch),
462	      seedFor(bundle),
463	    );
464	    const view = toWorldView(world, bundle, branch);
465	    return branch === undefined ? view : { ...view, branch };
466	  }
467	
468	  /**
469	   * What moved between the map as it was written and the map with this branch
470	   * folded onto it.
471	   *
472	   * @param request Which map and which branch.
473	   */
474	  async readDiff(request: DiffRequest): Promise<DiffView> {
475	    const bundle = await this.readBundle(request.baseId);
476	    const difference = await readDiff(request.baseId, sendable(request.branch), seedFor(bundle));
477	    // The claims are needed only for their words and their kinds, so the rail
478	    // can name an ending rather than print its identifier.
479	    const claims = bundle.graph.propositions
480	      .map(toClaim)
481	      .concat(request.branch.claims.map((claim) => claim));
482	    return toDiffView(difference, claims);
483	  }
484	
485	  /**
486	   * The number on one arrow: its target, with its cause **supposed** true.
487	   *
488	   * @param request Which map, which branch, and which arrow.
489	   */
490	  async readConditional(request: ConditionalRequest): Promise<Known<Ranged>> {
491	    const bundle = await this.readBundle(request.baseId);
492	    const answer = await readConditional(
493	      request.baseId,
494	      request.branch === undefined ? null : sendable(request.branch),
495	      seedFor(bundle),
496	      request.linkId,
497	    );
498	    return filled(answer);
499	  }
500	}
