1	/**
2	 * The whole screen: the launchpad, and the map you open from it.
3	 *
4	 * Two states and nothing in between. The launchpad names the two ways into the
5	 * tool and offers the four examples from the brief; opening the one that is
6	 * built swaps the page for the map. Everything on the map came over the wire
7	 * from the server, and the line under it says which address it came from — this
8	 * product does not put a number on screen that a reader cannot trace to an
9	 * input, a rule or a source, and that includes numbers a stored example happens
10	 * to carry.
11	 *
12	 * There is no spinner anywhere, and there never will be. A spinner says "wait"
13	 * without saying what for. While something is on its way the screen says what
14	 * it is waiting for and where it asked.
15	 */
16	
17	import { useCallback, useEffect, useMemo, useRef, useState } from "react";
18	import { branchAnnouncement } from "./a11y/announcement";
19	import { outlineOf } from "./a11y/sentences";
20	import type { About, FixtureSummary, Health, Readiness } from "./api/client";
21	import { RefusedBranch, readAbout, readExampleList, readHealth, readReadiness } from "./api/client";
22	import { BranchPanel, InterventionPanel } from "./components/BranchPanel";
23	import { type Command, CommandPalette } from "./components/CommandPalette";
24	import { DeltaRail } from "./components/DeltaRail";
25	import { Inspector } from "./components/Inspector";
26	import { Launchpad } from "./components/Launchpad";
27	import { Outline } from "./components/Outline";
28	import { Refusal } from "./components/Refusal";
29	import { ShortcutsSheet } from "./components/ShortcutsSheet";
30	import { MapCanvas } from "./graph/Canvas";
31	import { bothPaintings, type Engine, railRows } from "./graph/diff/branchWorld";
32	import { endings, NO_SUMMARY_YET } from "./graph/diff/endings";
33	import { tileHeight } from "./graph/geometry";
34	import type { MapKeys } from "./keyboard/useMapKeys";
35	import {
36	  type Absence,
37	  ApiWorldSource,
38	  appendEdit,
39	  type BranchView,
40	  branchesOf,
41	  type ClaimView,
42	  type DiffView,
43	  type Edit,
44	  FixtureWorldSource,
45	  forkBranch,
46	  type Known,
47	  type LinkView,
48	  openBranch,
49	  type Ranged,
50	  type Reason,
51	  type Selection,
52	  type WorldSource,
53	  type WorldView,
54	  workshopOf,
55	} from "./world";
56	
57	/**
58	 * Everything the screen can know about one thing it asked for. Three states and
59	 * no others, which is what makes every pixel below traceable to a cause.
60	 */
61	type Answer<Reading> =
62	  | { state: "asking" }
63	  | { state: "answered"; value: Reading }
64	  | { state: "failed"; reason: string };
65	
66	/** How loud a row's words are. Emphasis only — the words carry the meaning. */
67	type Tone = "good" | "quiet" | "loud";
68	
69	/** One row of the strip at the foot of the launchpad. */
70	interface Reading {
71	  /** What is being reported, such as "server". */
72	  label: string;
73	  /** The value from the server, or null while the request is still in flight. */
74	  value: string | null;
75	  /** A mark beside the words. Never the only carrier of meaning. */
76	  glyph: string;
77	  /** What the value means, in plain words. On a failure, this is the failure. */
78	  state: string;
79	  tone: Tone;
80	}
81	
82	/** Turn whatever a failed request threw into one sentence. */
83	function inWords(reason: unknown): string {
84	  return reason instanceof Error ? reason.message : "The reason was not recorded.";
85	}
86	
87	/**
88	 * Make one request when the screen first appears and report where it got to.
89	 *
90	 * @param ask The request to make. It must be the same function on every render,
91	 *   so pass one defined at module level rather than one written inline.
92	 */
93	function useAnswer<Reading>(ask: () => Promise<Reading>): Answer<Reading> {
94	  const [answer, setAnswer] = useState<Answer<Reading>>({ state: "asking" });
95	
96	  useEffect(() => {
97	    let stillOnScreen = true;
98	    ask().then(
99	      (value) => {
100	        if (stillOnScreen) {
101	          setAnswer({ state: "answered", value });
102	        }
103	      },
104	      (reason: unknown) => {
105	        if (stillOnScreen) {
106	          setAnswer({ state: "failed", reason: inWords(reason) });
107	        }
108	      },
109	    );
110	    return () => {
111	      stillOnScreen = false;
112	    };
113	  }, [ask]);
114	
115	  return answer;
116	}
117	
118	/** The row that says whether the server answered at all. */
119	function serverReading(answer: Answer<Health>): Reading {
120	  switch (answer.state) {
121	    case "asking":
122	      return {
123	        label: "server",
124	        value: null,
125	        glyph: "○",
126	        state: "asking the server",
127	        tone: "quiet",
128	      };
129	    case "answered":
130	      return {
131	        label: "server",
132	        value: answer.value.status,
133	        glyph: "●",
134	        state: "reachable",
135	        tone: "good",
136	      };
137	    case "failed":
138	      return { label: "server", value: "—", glyph: "○", state: answer.reason, tone: "loud" };
139	  }
140	}
141	
142	/** The row that says whether a key for the language model is configured. */
143	function modelKeyReading(answer: Answer<Readiness>): Reading {
144	  switch (answer.state) {
145	    case "asking":
146	      return {
147	        label: "model key",
148	        value: null,
149	        glyph: "○",
150	        state: "asking the server",
151	        tone: "quiet",
152	      };
153	    case "answered":
154	      return answer.value.model_key_present
155	        ? {
156	            label: "model key",
157	            value: "present",
158	            glyph: "●",
159	            state: "ready to generate",
160	            tone: "good",
161	          }
162	        : {
163	            label: "model key",
164	            value: "absent",
165	            glyph: "○",
166	            state: "no key configured — generating a map is not built yet",
167	            tone: "quiet",
168	          };
169	    case "failed":
170	      return { label: "model key", value: "—", glyph: "○", state: answer.reason, tone: "loud" };
171	  }
172	}
173	
174	/** The row that says which build answered. */
175	function versionReading(answer: Answer<About>): Reading {
176	  switch (answer.state) {
177	    case "asking":
178	      return {
179	        label: "version",
180	        value: null,
181	        glyph: "○",
182	        state: "asking the server",
183	        tone: "quiet",
184	      };
185	    case "answered":
186	      return {
187	        label: "version",
188	        value: answer.value.version,
189	        glyph: "●",
190	        state: `reported by ${answer.value.name}`,
191	        tone: "good",
192	      };
193	    case "failed":
194	      return { label: "version", value: "—", glyph: "○", state: answer.reason, tone: "loud" };
195	  }
196	}
197	
198	/**
199	 * Why the three examples that need the model are not live, in one sentence.
200	 *
201	 * Read from the server's own answer rather than written into the page, so that
202	 * the reason on screen is the real one.
203	 */
204	function notLiveReason(answer: Answer<Readiness>): string {
205	  if (answer.state === "answered" && !answer.value.model_key_present) {
206	    return "Turning your own words into a map needs the model, and this server has no key for one.";
207	  }
208	  return "Turning your own words into a map is not built yet.";
209	}
210	
211	/**
212	 * One row: a label, the value the server gave, and what that value means.
213	 *
214	 * While the value is missing the cell holds a bar of the same height, so the
215	 * row does not change size when the answer arrives. There is no spinner: a bar
216	 * where the value will land says the same thing without pretending to spin.
217	 */
218	function StatusRow({ reading }: { reading: Reading }) {
219	  const waiting = reading.value === null;
220	  return (
221	    <div className="status-row">
222	      <dt className="status-label">{reading.label}</dt>
223	      <dd className="status-value" data-settled={waiting ? "no" : "yes"}>
224	        {waiting ? <span className="placeholder" aria-hidden="true" /> : reading.value}
225	      </dd>
226	      <dd className="status-state" data-tone={reading.tone}>
227	        <span className="glyph" aria-hidden="true">
228	          {reading.glyph}
229	        </span>
230	        <span className="state-words">{reading.state}</span>
231	      </dd>
232	    </div>
233	  );
234	}
235	
236	/** Which of the two screens is showing. */
237	type Screen =
238	  | { at: "launchpad" }
239	  | { at: "opening"; id: string }
240	  | {
241	      at: "map";
242	      world: WorldView;
243	      branches: readonly BranchView[];
244	      /**
245	       * Why the map on screen was read from the stored example rather than
246	       * worked out by the engine, or nothing when the engine answered.
247	       */
248	      insteadOfTheEngine: string | null;
249	    }
250	  | { at: "failed"; id: string; reason: string };
251	
252	/** How long the wires take to arrive, column by column, before the map settles. */
253	const WAVE_SETTLES_AFTER = 1200;
254	
255	/**
256	 * What stands where a likelihood would go while the engine is being asked for
257	 * one.
258	 *
259	 * The shared vocabulary has three ways of saying a number is not there, and
260	 * this is the third of them — *nothing has been computed* — because that is
261	 * exactly what is true while a question is in flight: the engine has been asked
262	 * and has not answered, so nothing has worked this number through the map
263	 * **yet**. It is not a fourth kind of absence and it is not a spinner: the map
264	 * on screen keeps its shape, the slots that will move say why they are empty,
265	 * and the line under the map says what has been asked for and where.
266	 */
267	const WHILE_ASKING: Absence = {
268	  kind: "no_engine",
269	  words: "no engine yet",
270	  reason:
271	    "The engine has been asked at /api/worlds for the map with this branch folded onto it, and " +
272	    "has not answered. Nothing has worked this number through the map yet.",
273	};
274	
275	/**
276	 * What stands where a likelihood would go when the engine **refused** the
277	 * branch.
278	 *
279	 * Not "no engine yet": the engine is there and it answered — it said the branch
280	 * does not fit the map, and it said why. The words have to be true of that, and
281	 * `spec/vocabulary.md`'s three rows are all about a number nobody has worked
282	 * out rather than one that could not be. **A fourth row is proposed** — *the
283	 * engine refused the branch these numbers would come from* → **not worked out**
284	 * — and until that lands this uses those words with the reason naming the
285	 * refusal, because the nearest existing row says the wrong thing.
286	 */
287	const REFUSED: Absence = {
288	  kind: "no_engine",
289	  words: "not worked out",
290	  reason:
291	    "The engine would not work this map out from this branch: the branch does not fit the map. " +
292	    "Every reason is beside the map, and nothing on the map has changed.",
293	};
294	
295	/** What stands there when the engine could not be reached at all. */
296	function unreachable(reason: string): Absence {
297	  return {
298	    kind: "no_engine",
299	    words: "not worked out",
300	    reason: `The engine did not answer, so this number was never worked out. ${reason}`,
301	  };
302	}
303	
304	/**
305	 * Everything the engine has said about the branch that is open, and whether it
306	 * has said it yet.
307	 */
308	type Answered =
309	  | { at: "asking" }
310	  | { at: "answered"; computed: { now: WorldView; change: DiffView } }
311	  | { at: "refused"; reasons: readonly Reason[] }
312	  | { at: "failed"; reason: string }
313	  | { at: "nothing-open" };
314	
315	/**
316	 * Where the engine has got to, in the one shape the picture reads.
317	 *
318	 * Every state but *nothing is open* reserves the room an answer will take and
319	 * says why it is not there yet, so the map is the same size before and after the
320	 * answer lands and nothing on it jumps.
321	 */
322	function engineState(answer: Answered): Engine | undefined {
323	  switch (answer.at) {
324	    case "answered":
325	      return { at: "answered", now: answer.computed.now, change: answer.computed.change };
326	    case "asking":
327	      return { at: "waiting", absence: WHILE_ASKING };
328	    case "refused":
329	      return { at: "waiting", absence: REFUSED };
330	    case "failed":
331	      return { at: "waiting", absence: unreachable(answer.reason) };
332	    case "nothing-open":
333	      return undefined;
334	  }
335	}
336	
337	/**
338	 * How tall a box this claim's tile needs, with room for how far its number
339	 * moved.
340	 *
341	 * A tile is as tall as its own content, and the layout has to know that before
342	 * the browser has drawn one — so the height is a plain function of the claim.
343	 * This adds one thing to it: **how far the number moved gets a line of its own**
344	 * under whatever the edits had to say. On the busiest tile on the map, *Supposed
345	 * · Oct 1 → Retracted · Oct 2 · by "…"* already runs to three lines, and
346	 * stringing a reading on the end of that run pushes a line out of the box.
347	 *
348	 * The extra line is measured rather than written down: the words' block and the
349	 * reading's block are each measured on their own and the empty tile is counted
350	 * once. So if the badge line height ever changes, this changes with it, and
351	 * there is no second copy of a number here to fall out of step.
352	 *
353	 * @param claim The claim the tile is for.
354	 */
355	function roomFor(claim: ClaimView): number {
356	  const badges = claim.badges ?? [];
357	  const said = badges.filter((badge) => badge.movement !== true);
358	  const moved = badges.filter((badge) => badge.movement === true);
359	  if (said.length === 0 || moved.length === 0) {
360	    return tileHeight(claim);
361	  }
362	  const withWords = tileHeight({ ...claim, badges: said });
363	  const withReading = tileHeight({ ...claim, badges: moved });
364	  const withNeither = tileHeight({ ...claim, badges: [] });
365	  return withWords + withReading - withNeither;
366	}
367	
368	/** Turn whatever the engine threw into either a list of reasons or one sentence. */
369	function asAnswer(reason: unknown): Answered {
370	  if (reason instanceof RefusedBranch) {
371	    return { at: "refused", reasons: reason.reasons };
372	  }
373	  return { at: "failed", reason: inWords(reason) };
374	}
375	
376	/**
377	 * The map, the panel beside it, and everything you can do to both.
378	 *
379	 * Three things live here rather than inside the map, because all three are about
380	 * the whole screen rather than about the picture: which branch is open, which of
381	 * the two worlds is painted, and what the keyboard is on.
382	 */
383	function MapScreen({
384	  base,
385	  branches,
386	  source,
387	  insteadOfTheEngine,
388	  onLeave,
389	}: {
390	  base: WorldView;
391	  branches: readonly BranchView[];
392	  /** Where a branch's world, its difference and an arrow's number are asked for. */
393	  source: WorldSource;
394	  /** Why this map is the stored example rather than the engine's, or nothing. */
395	  insteadOfTheEngine: string | null;
396	  onLeave: () => void;
397	}) {
398	  const [shop, setShop] = useState(() => workshopOf(branches));
399	  const [showing, setShowing] = useState<"now" | "before">("now");
400	  const [selection, setSelection] = useState<Selection>(null);
401	  const [focused, setFocused] = useState<string | null>(null);
402	  const [dock, setDock] = useState<"panel" | "outline" | "away">("panel");
403	  const [onlyColumn, setOnlyColumn] = useState<{
404	    layer: number;
405	    claims: readonly string[];
406	  } | null>(null);
407	  const [overlay, setOverlay] = useState<"palette" | "sheet" | null>(null);
408	  const [intervening, setIntervening] = useState(false);
409	  const [naming, setNaming] = useState(false);
410	  const [status, setStatus] = useState(
411	    "Press ? for every key. j and k walk a column; h and l follow the wires.",
412	  );
413	  const [arriving, setArriving] = useState(true);
414	  const lastBranch = useRef<string | null>(null);
415	
416	  const open = shop.branches.find((branch) => branch.id === shop.openId);
417	
418	  // What the engine says about the branch that is open. It is asked again
419	  // whenever the branch changes — which is what makes the six buttons move
420	  // numbers: pressing one appends an edit, and the whole branch goes back.
421	  const [answer, setAnswer] = useState<Answered>({ at: "nothing-open" });
422	  useEffect(() => {
423	    if (open === undefined) {
424	      setAnswer({ at: "nothing-open" });
425	      return;
426	    }
427	    let stillWanted = true;
428	    setAnswer({ at: "asking" });
429	    Promise.all([
430	      source.readWorld({ baseId: base.baseId, branch: open }),
431	      source.readDiff({ baseId: base.baseId, branch: open }),
432	    ]).then(
433	      ([now, change]) => {
434	        if (stillWanted) {
435	          setAnswer({ at: "answered", computed: { now, change } });
436	        }
437	      },
438	      (failure: unknown) => {
439	        if (stillWanted) {
440	          setAnswer(asAnswer(failure));
441	        }
442	      },
443	    );
444	    return () => {
445	      // An answer to a question the reader has moved on from is thrown away
446	      // rather than drawn: a map that flickers back to an older branch because
447	      // a slower request finished last is a map nobody can trust.
448	      stillWanted = false;
449	    };
450	    // The branch itself is what this hangs on, and that is enough: appending an
451	    // edit hands back a new branch rather than changing the one that was there
452	    // — a branch is an audit trail and nothing rewrites one — so every press of
453	    // a button is a new question here, and nothing else is.
454	  }, [source, base.baseId, open]);
455	
456	  const engine = engineState(answer);
457	  const computed = answer.at === "answered" ? answer.computed : undefined;
458	
459	  // The numbers on the arrows, one at a time, kept once they arrive. Each one
460	  // costs a whole extra run of the map, so it is asked for when a reader selects
461	  // that arrow and never again for the same branch, seed and arrow.
462	  const [wireNumbers, setWireNumbers] = useState<ReadonlyMap<string, Known<Ranged>>>(new Map());
463	  const paintings = useMemo(
464	    () => (open === undefined ? null : bothPaintings(base, open, engine)),
465	    [base, open, engine],
466	  );
467	
468	  const painted = paintings === null ? base : showing === "now" ? paintings.now : paintings.before;
469	  const seed = painted.seed;
470	
471	  /** What names one arrow's number: which branch, which seed, which arrow. */
472	  const wireKey = useCallback(
473	    (linkId: string) => `${shop.openId ?? "as-written"}:${seed ?? "no-seed"}:${linkId}`,
474	    [shop.openId, seed],
475	  );
476	
477	  // The map as it is drawn: the world above, with any arrow number already
478	  // fetched put back on its own arrow.
479	  const world = useMemo((): WorldView => {
480	    if (wireNumbers.size === 0) {
481	      return painted;
482	    }
483	    return {
484	      ...painted,
485	      links: painted.links.map((link): LinkView => {
486	        const asked = wireNumbers.get(wireKey(link.id));
487	        return asked === undefined ? link : { ...link, conditional: asked };
488	      }),
489	    };
490	  }, [painted, wireNumbers, wireKey]);
491	
492	  /**
493	   * One box per claim, tall enough for whichever of the two paintings needs more
494	   * room — a claim grows badges when an edit touched it. Reserving the taller box
495	   * is what lets the union be laid out once and painted twice with nothing
496	   * moving.
497	   */
498	  const heights = useMemo(() => {
499	    if (paintings === null) {
500	      return undefined;
501	    }
502	    const reserved = new Map<string, number>();
503	    for (const side of [paintings.now, paintings.before]) {
504	      for (const claim of side.claims) {
505	        reserved.set(claim.id, Math.max(reserved.get(claim.id) ?? 0, roomFor(claim)));
506	      }
507	    }
508	    return reserved;
509	  }, [paintings]);
510	
511	  // The endings the edit reaches. With the engine, its own ranked rows, in its
512	  // own order; without it, the reachable endings in map order, and the rail
513	  // says on its own face which of the two it is showing.
514	  const rows = useMemo(
515	    () =>
516	      computed !== undefined
517	        ? railRows(paintings?.now ?? base, computed.change)
518	        : paintings === null
519	          ? []
520	          : endings(paintings.now),
521	    [computed, paintings, base],
522	  );
523	  const outline = useMemo(() => outlineOf(world), [world]);
524	
525	  // What the branch did, said out loud for a reader who is not looking at the
526	  // picture. It is said twice, because the two halves arrive at different
527	  // moments: the shape the instant the branch opens, and the counts when the
528	  // engine answers. The live region is polite, so the second line waits for a
529	  // pause rather than cutting across the first.
530	  const announcement = useMemo(
531	    () => (paintings === null ? "" : branchAnnouncement(paintings.now, computed?.change)),
532	    [paintings, computed],
533	  );
534	
535	  // One arrow's own number, asked for when the reader selects that arrow and
536	  // kept afterwards. It is fetched here rather than by the wire because no
537	  // component in this product talks to the network, and because the answer
538	  // belongs to the whole screen: the panel and the plate on the wire read the
539	  // same one.
540	  useEffect(() => {
541	    if (selection?.kind !== "wire") {
542	      return;
543	    }
544	    const key = wireKey(selection.id);
545	    if (wireNumbers.has(key)) {
546	      return;
547	    }
548	    let stillWanted = true;
549	    source
550	      .readConditional({ baseId: base.baseId, branch: open, linkId: selection.id })
551	      .then(
552	        (slot) => slot,
553	        (failure: unknown): Known<Ranged> => ({
554	          absence: {
555	            kind: "no_engine",
556	            words: "no engine yet",
557	            reason: inWords(failure),
558	          },
559	        }),
560	      )
561	      .then((slot) => {
562	        if (stillWanted) {
563	          setWireNumbers((was) => new Map(was).set(key, slot));
564	        }
565	      });
566	    return () => {
567	      stillWanted = false;
568	    };
569	  }, [selection, source, base.baseId, open, wireKey, wireNumbers]);
570	
571	  // A branch has just been opened or made. Three things follow, in this order:
572	  // the map says out loud what the branch did, the wires arrive again in causal
573	  // order, and — because creating a claim moves focus to it — the keyboard lands
574	  // on the claim the branch added, so the view frames the thing you just made
575	  // rather than leaving you to hunt for it.
576	  useEffect(() => {
577	    if (shop.openId === lastBranch.current) {
578	      return;
579	    }
580	    lastBranch.current = shop.openId;
581	    setShowing("now");
582	    setArriving(true);
583	    if (paintings === null) {
584	      return;
585	    }
586	    const arrived = paintings.now.claims.find((claim) => claim.diff === "added");
587	    if (arrived !== undefined) {
588	      setFocused(arrived.id);
589	      setSelection({ kind: "claim", id: arrived.id });
590	      setStatus(`your edit added this claim · ${arrived.claim}`);
591	    }
592	  }, [shop.openId, paintings]);
593	
594	  // The wave settles on its own clock, and on nothing else.
595	  //
596	  // **It has to be its own effect.** The one above runs again whenever the
597	  // picture changes — and the picture changes when the engine answers, which is
598	  // a moment or two after a branch is opened. A timer started up there would be
599	  // cleared by that second run and never started again, and the map would stay
600	  // mid-arrival for ever, which is to say invisible.
601	  useEffect(() => {
602	    if (!arriving) {
603	      return;
604	    }
605	    const settles = window.setTimeout(() => setArriving(false), WAVE_SETTLES_AFTER);
606	    return () => window.clearTimeout(settles);
607	  }, [arriving]);
608	
609	  const edit = useCallback((made: Edit) => {
610	    setShop((was) =>
611	      appendEdit(was.openId === null ? forkBranch(was, "Your own branch") : was, made),
612	    );
613	  }, []);
614	
615	  const keys: MapKeys = useMemo(
616	    () => ({
617	      intervene: () => {
618	        setDock("panel");
619	        setIntervening(true);
620	      },
621	      branch: () => {
622	        setDock("panel");
623	        setNaming(true);
624	      },
625	      flipWorlds: () => {
626	        if (paintings === null) {
627	          setStatus("there is nothing to flip to — no branch is open");
628	          return;
629	        }
630	        setShowing((was) => {
631	          const next = was === "now" ? "before" : "now";
632	          setStatus(
633	            next === "now"
634	              ? "the map with your edits"
635	              : "the map as it was written, with what your branch adds drawn faint",
636	          );
637	          return next;
638	        });
639	      },
640	      outline: () =>
641	        setDock((was) => {
642	          setOnlyColumn(null);
643	          return was === "outline" ? "panel" : "outline";
644	        }),
645	      panel: () => setDock((was) => (was === "away" ? "panel" : "away")),
646	      palette: () => setOverlay("palette"),
647	    }),
648	    [paintings],
649	  );
650	
651	  // ⌘K, ? and Escape work wherever you are on the screen, not only on the map,
652	  // because two of them are how you find out what the others do.
653	  useEffect(() => {
654	    const onKey = (event: KeyboardEvent): void => {
655	      const target = event.target as HTMLElement | null;
656	      const typing =
657	        target?.tagName === "INPUT" ||
658	        target?.tagName === "TEXTAREA" ||
659	        target?.isContentEditable === true;
660	      if ((event.metaKey || event.ctrlKey) && event.key.toLowerCase() === "k") {
661	        event.preventDefault();
662	        setOverlay((was) => (was === "palette" ? null : "palette"));
663	        return;
664	      }
665	      if (event.key === "Escape") {
666	        setOverlay(null);
667	        setIntervening(false);
668	        setNaming(false);
669	        return;
670	      }
671	      if (event.key === "?" && !typing) {
672	        event.preventDefault();
673	        setOverlay((was) => (was === "sheet" ? null : "sheet"));
674	      }
675	    };
676	    window.addEventListener("keydown", onKey);
677	    return () => window.removeEventListener("keydown", onKey);
678	  }, []);
679	
680	  const commands: Command[] = useMemo(() => {
681	    const made: Command[] = [
682	      {
683	        name: "The map as it was written",
684	        does: "Close the branch. Also the first row of the branch panel.",
685	        run: () => setShop((was) => openBranch(was, null)),
686	      },
687	      ...shop.branches.map((branch) => ({
688	        name: `Open the branch: ${branch.label}`,
689	        does: `${branch.edits.length} edits. Also a row in the branch panel.`,
690	        run: () => setShop((was) => openBranch(was, branch.id)),
691	      })),
692	      {
693	        name: "Flip between the two maps",
694	        does: "The same as pressing Space on the map. A hard switch, never a fade.",
695	        run: keys.flipWorlds,
696	      },
697	      {
698	        name: "Change this claim",
699	        does: "The six things you can do to it. The same as pressing E on the map.",
700	        run: keys.intervene,
701	      },
702	      {
703	        name: "Start a branch",
704	        does: "The same as pressing B on the map, and as the button in the branch panel.",
705	        run: keys.branch,
706	      },
707	      {
708	        name: "Read the map as a list",
709	        does: "The same as pressing O. Every claim, one sentence each.",
710	        run: () => {
711	          setOnlyColumn(null);
712	          setDock("outline");
713	        },
714	      },
715	      {
716	        name: "Show or hide the panel beside the map",
717	        does: "The same as pressing P, when you want the whole width for the map.",
718	        run: keys.panel,
719	      },
720	      {
721	        name: "Every key, on one sheet",
722	        does: "The same as pressing the question mark.",
723	        run: () => setOverlay("sheet"),
724	      },
725	      {
726	        name: "Back to the launchpad",
727	        does: "The same as the link at the top left.",
728	        run: onLeave,
729	      },
730	    ];
731	    return made;
732	  }, [shop.branches, keys, onLeave]);
733	
734	  const pick = useCallback((id: string) => {
735	    setFocused(id);
736	    setSelection({ kind: "claim", id });
737	  }, []);
738	
739	  return (
740	    <main className="page page--map">
741	      <header className="map-bar">
742	        <button className="map-bar__back" type="button" onClick={onLeave}>
743	          <span aria-hidden="true">←</span> Back to the launchpad
744	        </button>
745	        <h1 className="map-bar__title">{base.title}</h1>
746	        {open === undefined ? (
747	          <p className="map-bar__where">The map as it was written</p>
748	        ) : (
749	          <p className="map-bar__where">
750	            {/* A branch's hue rides on its name chip and its lane and nowhere
751	                else, and the chip always carries the branch's name — so which
752	                branch you are in is readable with no colour at all. */}
753	            <span className="map-bar__chip" data-hue={open.hue} aria-hidden="true" />
754	            {open.label}
755	            <span className="map-bar__side">
756	              {showing === "now" ? "with your edits" : "as it was written"}
757	            </span>
758	          </p>
759	        )}
760	        <button className="map-bar__sheet" type="button" onClick={() => setOverlay("sheet")}>
761	          Every key (?)
762	        </button>
763	      </header>
764	
765	      {/* The map and the panel, side by side. The panel is part of the screen
766	          rather than something that appears over it: there are no pop-ups
767	          anywhere in this product, and a dialog you have to dismiss would steal
768	          the map that makes the detail mean anything. */}
769	      <div className="map-body">
770	        <div className="map-stage">
771	          <MapCanvas
772	            world={world}
773	            selection={selection}
774	            onSelect={setSelection}
775	            focused={focused}
776	            onFocused={setFocused}
777	            heights={heights}
778	            mapKey={`${base.baseId}:${shop.openId ?? "as-written"}`}
779	            keys={keys}
780	            onStatus={setStatus}
781	            onOverflow={(column) => {
782	              setOnlyColumn(column);
783	              setDock("outline");
784	            }}
785	            arriving={arriving}
786	          />
787	          {overlay === "palette" ? (
788	            <CommandPalette open={true} onClose={() => setOverlay(null)} commands={commands} />
789	          ) : null}
790	          {overlay === "sheet" ? (
791	            <ShortcutsSheet open={true} onClose={() => setOverlay(null)} />
792	          ) : null}
793	          <p className="map-status">
794	            <span className="map-status__mark">last key</span>
795	            {status}
796	          </p>
797	        </div>
798	
799	        {dock === "away" ? null : (
800	          <aside className="dock" aria-label="The panel beside the map">
801	            {dock === "outline" ? (
802	              <Outline
803	                items={outline}
804	                onPick={pick}
805	                focused={focused}
806	                {...(onlyColumn === null
807	                  ? {}
808	                  : {
809	                      only: new Set(onlyColumn.claims),
810	                      filter:
811	                        `Only the claims in column ${onlyColumn.layer}, which is what the ` +
812	                        `collapsed tile on the map stands for. Press O for all of them.`,
813	                    })}
814	              />
815	            ) : (
816	              <>
817	                {intervening ? (
818	                  <InterventionPanel
819	                    world={world}
820	                    selection={selection}
821	                    onEdit={edit}
822	                    onClose={() => setIntervening(false)}
823	                  />
824	                ) : null}
825	                <BranchPanel
826	                  branches={shop.branches}
827	                  openId={shop.openId}
828	                  world={world}
829	                  onOpen={(id) => setShop((was) => openBranch(was, id))}
830	                  onFork={(label) => setShop((was) => forkBranch(was, label))}
831	                  naming={naming}
832	                  onNaming={setNaming}
833	                />
834	                {answer.at === "refused" ? (
835	                  <Refusal asking="this map" reasons={answer.reasons} />
836	                ) : null}
837	                {open === undefined ? null : (
838	                  <DeltaRail
839	                    rows={rows}
840	                    ranked={computed !== undefined}
841	                    summary={computed === undefined ? NO_SUMMARY_YET : computed.change.summary}
842	                  />
843	                )}
844	                <Inspector world={world} selection={selection} />
845	              </>
846	            )}
847	          </aside>
848	        )}
849	      </div>
850	
851	      {/* What a branch did, said out loud for a reader who is not looking at the
852	          picture. Polite: it waits for a pause rather than cutting across
853	          whatever is being read. */}
854	      <p className="map-live" aria-live="polite">
855	        {announcement}
856	      </p>
857	
858	      {/* Where every number on this map came from, and anything that is still on
859	          its way. There is no spinner here and never will be: a spinner says
860	          "wait" without saying what for, so the line says what has been asked
861	          and at which address, and the map keeps drawing the last answer while
862	          it waits. */}
863	      <div className="map-origin">
864	        <p className="map-origin__line">{world.origin}</p>
865	        {answer.at === "asking" ? <p className="map-origin__line">{WHILE_ASKING.reason}</p> : null}
866	        {answer.at === "failed" ? (
867	          <p className="map-origin__line">
868	            {`The engine did not answer, so this is the map's shape with an absence wherever a ` +
869	              `likelihood would have moved. ${answer.reason}`}
870	          </p>
871	        ) : null}
872	        {insteadOfTheEngine === null ? null : (
873	          <p className="map-origin__line">{insteadOfTheEngine}</p>
874	        )}
875	        {(world.warnings ?? []).map((warning) => (
876	          <p className="map-origin__line" key={warning}>
877	            {warning}
878	          </p>
879	        ))}
880	      </div>
881	    </main>
882	  );
883	}
884	
885	/**
886	 * Where maps come from: the engine.
887	 *
888	 * Every number on the map is worked out by it, from the stored map, the branch
889	 * and one seed. Nothing on this screen computes a likelihood, and nothing on
890	 * this screen shows one the engine did not produce.
891	 */
892	const DEFAULT_SOURCE: WorldSource = new ApiWorldSource();
893	
894	/**
895	 * Where maps come from when the engine cannot be reached.
896	 *
897	 * A map you can still read beats a blank screen. The stored example's claims,
898	 * arrows, dates and sources are all real and all still worth reading — what is
899	 * missing is the working-out, and the screen says so in a line under the map
900	 * rather than letting a hand-written likelihood pass for a computed one.
901	 */
902	const FALLBACK_SOURCE: WorldSource = new FixtureWorldSource();
903	
904	/**
905	 * The line under the map when the stored example is standing in for the engine.
906	 *
907	 * @param reason What went wrong, in the sentence the failure arrived with.
908	 */
909	function insteadOfTheEngine(reason: string): string {
910	  return (
911	    `The engine did not answer, so this map is the stored example exactly as it was written: ` +
912	    `its claims, arrows, dates and sources are real, and its likelihoods are the illustrative ` +
913	    `ones somebody wrote down rather than anything worked out. ${reason}`
914	  );
915	}
916	
917	/** What the screen needs. All three have defaults; all three exist so they can be swapped. */
918	export interface AppProps {
919	  /** Where maps and worlds come from. */
920	  readonly source?: WorldSource;
921	  /** Where they come from when the first one cannot answer. */
922	  readonly fallback?: WorldSource;
923	  /** How the list of stored examples is read. */
924	  readonly listExamples?: () => Promise<FixtureSummary[]>;
925	}
926	
927	/** The screen. */
928	export function App({
929	  source = DEFAULT_SOURCE,
930	  fallback = FALLBACK_SOURCE,
931	  listExamples = readExampleList,
932	}: AppProps = {}) {
933	  const health = useAnswer(readHealth);
934	  const readiness = useAnswer(readReadiness);
935	  const about = useAnswer(readAbout);
936	  const examples = useAnswer(listExamples);
937	
938	  const [screen, setScreen] = useState<Screen>({ at: "launchpad" });
939	  const [using, setUsing] = useState<WorldSource>(source);
940	
941	  const open = useCallback(
942	    (id: string) => {
943	      setScreen({ at: "opening", id });
944	      /**
945	       * The world and the map's own branches, together: the world is what gets
946	       * drawn, and the branches are the edits somebody already made to it, which
947	       * the panel lists and the diff view folds on.
948	       *
949	       * @param from Where to ask.
950	       */
951	      const ask = (from: WorldSource) =>
952	        Promise.all([from.readWorld({ baseId: id }), from.readBundle(id)]);
953	
954	      ask(source).then(
955	        ([world, bundle]) => {
956	          setUsing(source);
957	          setScreen({ at: "map", world, branches: branchesOf(bundle), insteadOfTheEngine: null });
958	        },
959	        (failure: unknown) => {
960	          // The engine could not answer. Rather than a blank screen, the stored
961	          // example — and a line under the map saying, in the failure's own
962	          // words, that these are not computed numbers.
963	          ask(fallback).then(
964	            ([world, bundle]) => {
965	              setUsing(fallback);
966	              setScreen({
967	                at: "map",
968	                world,
969	                branches: branchesOf(bundle),
970	                insteadOfTheEngine: insteadOfTheEngine(inWords(failure)),
971	              });
972	            },
973	            // Neither answered, which means the server itself is not there. That
974	            // is one sentence on the page, and a way back to the launchpad.
975	            (alsoFailed: unknown) => setScreen({ at: "failed", id, reason: inWords(alsoFailed) }),
976	          );
977	        },
978	      );
979	    },
980	    [source, fallback],
981	  );
982	
983	  const toLaunchpad = useCallback(() => setScreen({ at: "launchpad" }), []);
984	
985	  const readings = useMemo(
986	    () => [serverReading(health), modelKeyReading(readiness), versionReading(about)],
987	    [health, readiness, about],
988	  );
989	
990	  if (screen.at === "map") {
991	    return (
992	      <MapScreen
993	        base={screen.world}
994	        branches={screen.branches}
995	        source={using}
996	        insteadOfTheEngine={screen.insteadOfTheEngine}
997	        onLeave={toLaunchpad}
998	      />
999	    );
1000	  }
1001	
1002	  if (screen.at !== "launchpad") {
1003	    return (
1004	      <main className="page page--map">
1005	        <header className="map-bar">
1006	          <button className="map-bar__back" type="button" onClick={toLaunchpad}>
1007	            <span aria-hidden="true">←</span> Back to the launchpad
1008	          </button>
1009	          <h1 className="map-bar__title">Strait of Hormuz</h1>
1010	        </header>
1011	
1012	        <div className="map-waiting">
1013	          <p className="map-waiting__line">
1014	            {screen.at === "opening"
1015	              ? `Reading the map from /api/fixtures/${screen.id} and asking /api/worlds to work ` +
1016	                `its likelihoods through.`
1017	              : screen.reason}
1018	          </p>
1019	        </div>
1020	      </main>
1021	    );
1022	  }
1023	
1024	  return (
1025	    <main className="page">
1026	      <div className="column">
1027	        <header className="masthead">
1028	          <h1 className="wordmark">Katalyst</h1>
1029	          <p className="purpose">
1030	            Type an event you think will happen. See what it would cause, step by step, ending in
1031	            trades.
1032	          </p>
1033	        </header>
1034	
1035	        <Launchpad
1036	          examples={examples.state === "answered" ? examples.value : null}
1037	          failure={examples.state === "failed" ? examples.reason : null}
1038	          notLiveReason={notLiveReason(readiness)}
1039	          onOpen={open}
1040	        />
1041	
1042	        <section aria-labelledby="status-heading">
1043	          <h2 className="section-heading" id="status-heading">
1044	            What this build can do right now
1045	          </h2>
1046	          <dl className="status-strip">
1047	            {readings.map((reading) => (
1048	              <StatusRow key={reading.label} reading={reading} />
1049	            ))}
1050	          </dl>
1051	          <p className="provenance">
1052	            Every reading above came from the server, at <code>/api/healthz</code>,{" "}
1053	            <code>/api/readyz</code> and <code>/api/about</code>. The examples came from{" "}
1054	            <code>/api/fixtures</code>. Nothing on this screen is written into the page.
1055	          </p>
1056	        </section>
1057	      </div>
1058	    </main>
1059	  );
1060	}
