/**
 * The whole screen: the launchpad, and the map you open from it.
 *
 * Two states and nothing in between. The launchpad names the two ways into the
 * tool and offers the four examples from the brief; opening the one that is
 * built swaps the page for the map. Everything on the map came over the wire
 * from the server, and the line under it says which address it came from — this
 * product does not put a number on screen that a reader cannot trace to an
 * input, a rule or a source, and that includes numbers a stored example happens
 * to carry.
 *
 * There is no spinner anywhere, and there never will be. A spinner says "wait"
 * without saying what for. While something is on its way the screen says what
 * it is waiting for and where it asked.
 */

import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { branchAnnouncement } from "./a11y/announcement";
import { outlineOf } from "./a11y/sentences";
import type { About, FixtureSummary, Health, Readiness } from "./api/client";
import { RefusedBranch, readAbout, readExampleList, readHealth, readReadiness } from "./api/client";
import { BranchPanel, InterventionPanel } from "./components/BranchPanel";
import { type Command, CommandPalette } from "./components/CommandPalette";
import { DeltaRail } from "./components/DeltaRail";
import { Inspector } from "./components/Inspector";
import { Launchpad } from "./components/Launchpad";
import { Outline } from "./components/Outline";
import { Refusal } from "./components/Refusal";
import { ShortcutsSheet } from "./components/ShortcutsSheet";
import { MapCanvas } from "./graph/Canvas";
import { bothPaintings, type Engine, railRows } from "./graph/diff/branchWorld";
import { endings, NO_SUMMARY_YET } from "./graph/diff/endings";
import { tileHeight } from "./graph/geometry";
import type { MapKeys } from "./keyboard/useMapKeys";
import {
  type Absence,
  ApiWorldSource,
  appendEdit,
  type BranchView,
  branchesOf,
  type ClaimView,
  type DiffView,
  type Edit,
  FixtureWorldSource,
  forkBranch,
  type Known,
  type LinkView,
  openBranch,
  type Ranged,
  type Reason,
  type Selection,
  type WorldSource,
  type WorldView,
  workshopOf,
} from "./world";

/**
 * Everything the screen can know about one thing it asked for. Three states and
 * no others, which is what makes every pixel below traceable to a cause.
 */
type Answer<Reading> =
  | { state: "asking" }
  | { state: "answered"; value: Reading }
  | { state: "failed"; reason: string };

/** How loud a row's words are. Emphasis only — the words carry the meaning. */
type Tone = "good" | "quiet" | "loud";

/** One row of the strip at the foot of the launchpad. */
interface Reading {
  /** What is being reported, such as "server". */
  label: string;
  /** The value from the server, or null while the request is still in flight. */
  value: string | null;
  /** A mark beside the words. Never the only carrier of meaning. */
  glyph: string;
  /** What the value means, in plain words. On a failure, this is the failure. */
  state: string;
  tone: Tone;
}

/** Turn whatever a failed request threw into one sentence. */
function inWords(reason: unknown): string {
  return reason instanceof Error ? reason.message : "The reason was not recorded.";
}

/**
 * Make one request when the screen first appears and report where it got to.
 *
 * @param ask The request to make. It must be the same function on every render,
 *   so pass one defined at module level rather than one written inline.
 */
function useAnswer<Reading>(ask: () => Promise<Reading>): Answer<Reading> {
  const [answer, setAnswer] = useState<Answer<Reading>>({ state: "asking" });

  useEffect(() => {
    let stillOnScreen = true;
    ask().then(
      (value) => {
        if (stillOnScreen) {
          setAnswer({ state: "answered", value });
        }
      },
      (reason: unknown) => {
        if (stillOnScreen) {
          setAnswer({ state: "failed", reason: inWords(reason) });
        }
      },
    );
    return () => {
      stillOnScreen = false;
    };
  }, [ask]);

  return answer;
}

/** The row that says whether the server answered at all. */
function serverReading(answer: Answer<Health>): Reading {
  switch (answer.state) {
    case "asking":
      return {
        label: "server",
        value: null,
        glyph: "○",
        state: "asking the server",
        tone: "quiet",
      };
    case "answered":
      return {
        label: "server",
        value: answer.value.status,
        glyph: "●",
        state: "reachable",
        tone: "good",
      };
    case "failed":
      return { label: "server", value: "—", glyph: "○", state: answer.reason, tone: "loud" };
  }
}

/** The row that says whether a key for the language model is configured. */
function modelKeyReading(answer: Answer<Readiness>): Reading {
  switch (answer.state) {
    case "asking":
      return {
        label: "model key",
        value: null,
        glyph: "○",
        state: "asking the server",
        tone: "quiet",
      };
    case "answered":
      return answer.value.model_key_present
        ? {
            label: "model key",
            value: "present",
            glyph: "●",
            state: "ready to generate",
            tone: "good",
          }
        : {
            label: "model key",
            value: "absent",
            glyph: "○",
            state: "no key configured — generating a map is not built yet",
            tone: "quiet",
          };
    case "failed":
      return { label: "model key", value: "—", glyph: "○", state: answer.reason, tone: "loud" };
  }
}

/** The row that says which build answered. */
function versionReading(answer: Answer<About>): Reading {
  switch (answer.state) {
    case "asking":
      return {
        label: "version",
        value: null,
        glyph: "○",
        state: "asking the server",
        tone: "quiet",
      };
    case "answered":
      return {
        label: "version",
        value: answer.value.version,
        glyph: "●",
        state: `reported by ${answer.value.name}`,
        tone: "good",
      };
    case "failed":
      return { label: "version", value: "—", glyph: "○", state: answer.reason, tone: "loud" };
  }
}

/**
 * Why the three examples that need the model are not live, in one sentence.
 *
 * Read from the server's own answer rather than written into the page, so that
 * the reason on screen is the real one.
 */
function notLiveReason(answer: Answer<Readiness>): string {
  if (answer.state === "answered" && !answer.value.model_key_present) {
    return "Turning your own words into a map needs the model, and this server has no key for one.";
  }
  return "Turning your own words into a map is not built yet.";
}

/**
 * One row: a label, the value the server gave, and what that value means.
 *
 * While the value is missing the cell holds a bar of the same height, so the
 * row does not change size when the answer arrives. There is no spinner: a bar
 * where the value will land says the same thing without pretending to spin.
 */
function StatusRow({ reading }: { reading: Reading }) {
  const waiting = reading.value === null;
  return (
    <div className="status-row">
      <dt className="status-label">{reading.label}</dt>
      <dd className="status-value" data-settled={waiting ? "no" : "yes"}>
        {waiting ? <span className="placeholder" aria-hidden="true" /> : reading.value}
      </dd>
      <dd className="status-state" data-tone={reading.tone}>
        <span className="glyph" aria-hidden="true">
          {reading.glyph}
        </span>
        <span className="state-words">{reading.state}</span>
      </dd>
    </div>
  );
}

/** Which of the two screens is showing. */
type Screen =
  | { at: "launchpad" }
  | { at: "opening"; id: string }
  | {
      at: "map";
      world: WorldView;
      branches: readonly BranchView[];
      /**
       * Why the map on screen was read from the stored example rather than
       * worked out by the engine, or nothing when the engine answered.
       */
      insteadOfTheEngine: string | null;
    }
  | { at: "failed"; id: string; reason: string };

/** How long the wires take to arrive, column by column, before the map settles. */
const WAVE_SETTLES_AFTER = 1200;

/**
 * What stands where a likelihood would go while the engine is being asked for
 * one.
 *
 * The shared vocabulary has three ways of saying a number is not there, and
 * this is the third of them — *nothing has been computed* — because that is
 * exactly what is true while a question is in flight: the engine has been asked
 * and has not answered, so nothing has worked this number through the map
 * **yet**. It is not a fourth kind of absence and it is not a spinner: the map
 * on screen keeps its shape, the slots that will move say why they are empty,
 * and the line under the map says what has been asked for and where.
 */
const WHILE_ASKING: Absence = {
  kind: "no_engine",
  words: "no engine yet",
  reason:
    "The engine has been asked at /api/worlds for the map with this branch folded onto it, and " +
    "has not answered. Nothing has worked this number through the map yet.",
};

/**
 * What stands where a likelihood would go when the engine **refused** the
 * branch.
 *
 * Not "no engine yet": the engine is there and it answered — it said the branch
 * does not fit the map, and it said why. The words have to be true of that, and
 * `spec/vocabulary.md`'s three rows are all about a number nobody has worked
 * out rather than one that could not be. **A fourth row is proposed** — *the
 * engine refused the branch these numbers would come from* → **not worked out**
 * — and until that lands this uses those words with the reason naming the
 * refusal, because the nearest existing row says the wrong thing.
 */
const REFUSED: Absence = {
  kind: "no_engine",
  words: "not worked out",
  reason:
    "The engine would not work this map out from this branch: the branch does not fit the map. " +
    "Every reason is beside the map, and nothing on the map has changed.",
};

/** What stands there when the engine could not be reached at all. */
function unreachable(reason: string): Absence {
  return {
    kind: "no_engine",
    words: "not worked out",
    reason: `The engine did not answer, so this number was never worked out. ${reason}`,
  };
}

/**
 * Everything the engine has said about the branch that is open, and whether it
 * has said it yet.
 */
type Answered =
  | { at: "asking" }
  | { at: "answered"; computed: { now: WorldView; change: DiffView } }
  | { at: "refused"; reasons: readonly Reason[] }
  | { at: "failed"; reason: string }
  | { at: "nothing-open" };

/**
 * Where the engine has got to, in the one shape the picture reads.
 *
 * Every state but *nothing is open* reserves the room an answer will take and
 * says why it is not there yet, so the map is the same size before and after the
 * answer lands and nothing on it jumps.
 */
function engineState(answer: Answered): Engine | undefined {
  switch (answer.at) {
    case "answered":
      return { at: "answered", now: answer.computed.now, change: answer.computed.change };
    case "asking":
      return { at: "waiting", absence: WHILE_ASKING };
    case "refused":
      return { at: "waiting", absence: REFUSED };
    case "failed":
      return { at: "waiting", absence: unreachable(answer.reason) };
    case "nothing-open":
      return undefined;
  }
}

/**
 * How tall a box this claim's tile needs, with room for how far its number
 * moved.
 *
 * A tile is as tall as its own content, and the layout has to know that before
 * the browser has drawn one — so the height is a plain function of the claim.
 * This adds one thing to it: **how far the number moved gets a line of its own**
 * under whatever the edits had to say. On the busiest tile on the map, *Supposed
 * · Oct 1 → Retracted · Oct 2 · by "…"* already runs to three lines, and
 * stringing a reading on the end of that run pushes a line out of the box.
 *
 * The extra line is measured rather than written down: the words' block and the
 * reading's block are each measured on their own and the empty tile is counted
 * once. So if the badge line height ever changes, this changes with it, and
 * there is no second copy of a number here to fall out of step.
 *
 * @param claim The claim the tile is for.
 */
function roomFor(claim: ClaimView): number {
  const badges = claim.badges ?? [];
  const said = badges.filter((badge) => badge.movement !== true);
  const moved = badges.filter((badge) => badge.movement === true);
  if (said.length === 0 || moved.length === 0) {
    return tileHeight(claim);
  }
  const withWords = tileHeight({ ...claim, badges: said });
  const withReading = tileHeight({ ...claim, badges: moved });
  const withNeither = tileHeight({ ...claim, badges: [] });
  return withWords + withReading - withNeither;
}

/** Turn whatever the engine threw into either a list of reasons or one sentence. */
function asAnswer(reason: unknown): Answered {
  if (reason instanceof RefusedBranch) {
    return { at: "refused", reasons: reason.reasons };
  }
  return { at: "failed", reason: inWords(reason) };
}

/**
 * The map, the panel beside it, and everything you can do to both.
 *
 * Three things live here rather than inside the map, because all three are about
 * the whole screen rather than about the picture: which branch is open, which of
 * the two worlds is painted, and what the keyboard is on.
 */
function MapScreen({
  base,
  branches,
  source,
  insteadOfTheEngine,
  onLeave,
}: {
  base: WorldView;
  branches: readonly BranchView[];
  /** Where a branch's world, its difference and an arrow's number are asked for. */
  source: WorldSource;
  /** Why this map is the stored example rather than the engine's, or nothing. */
  insteadOfTheEngine: string | null;
  onLeave: () => void;
}) {
  const [shop, setShop] = useState(() => workshopOf(branches));
  const [showing, setShowing] = useState<"now" | "before">("now");
  const [selection, setSelection] = useState<Selection>(null);
  const [focused, setFocused] = useState<string | null>(null);
  const [dock, setDock] = useState<"panel" | "outline" | "away">("panel");
  const [onlyColumn, setOnlyColumn] = useState<{
    layer: number;
    claims: readonly string[];
  } | null>(null);
  const [overlay, setOverlay] = useState<"palette" | "sheet" | null>(null);
  const [intervening, setIntervening] = useState(false);
  const [naming, setNaming] = useState(false);
  const [status, setStatus] = useState(
    "Press ? for every key. j and k walk a column; h and l follow the wires.",
  );
  const [arriving, setArriving] = useState(true);
  const lastBranch = useRef<string | null>(null);

  const open = shop.branches.find((branch) => branch.id === shop.openId);

  // What the engine says about the branch that is open. It is asked again
  // whenever the branch changes — which is what makes the six buttons move
  // numbers: pressing one appends an edit, and the whole branch goes back.
  const [answer, setAnswer] = useState<Answered>({ at: "nothing-open" });
  useEffect(() => {
    if (open === undefined) {
      setAnswer({ at: "nothing-open" });
      return;
    }
    let stillWanted = true;
    setAnswer({ at: "asking" });
    Promise.all([
      source.readWorld({ baseId: base.baseId, branch: open }),
      source.readDiff({ baseId: base.baseId, branch: open }),
    ]).then(
      ([now, change]) => {
        if (stillWanted) {
          setAnswer({ at: "answered", computed: { now, change } });
        }
      },
      (failure: unknown) => {
        if (stillWanted) {
          setAnswer(asAnswer(failure));
        }
      },
    );
    return () => {
      // An answer to a question the reader has moved on from is thrown away
      // rather than drawn: a map that flickers back to an older branch because
      // a slower request finished last is a map nobody can trust.
      stillWanted = false;
    };
    // The branch itself is what this hangs on, and that is enough: appending an
    // edit hands back a new branch rather than changing the one that was there
    // — a branch is an audit trail and nothing rewrites one — so every press of
    // a button is a new question here, and nothing else is.
  }, [source, base.baseId, open]);

  const engine = engineState(answer);
  const computed = answer.at === "answered" ? answer.computed : undefined;

  // The numbers on the arrows, one at a time, kept once they arrive. Each one
  // costs a whole extra run of the map, so it is asked for when a reader selects
  // that arrow and never again for the same branch, seed and arrow.
  const [wireNumbers, setWireNumbers] = useState<ReadonlyMap<string, Known<Ranged>>>(new Map());
  const paintings = useMemo(
    () => (open === undefined ? null : bothPaintings(base, open, engine)),
    [base, open, engine],
  );

  const painted = paintings === null ? base : showing === "now" ? paintings.now : paintings.before;
  const seed = painted.seed;

  /** What names one arrow's number: which branch, which seed, which arrow. */
  const wireKey = useCallback(
    (linkId: string) => `${shop.openId ?? "as-written"}:${seed ?? "no-seed"}:${linkId}`,
    [shop.openId, seed],
  );

  // The map as it is drawn: the world above, with any arrow number already
  // fetched put back on its own arrow.
  const world = useMemo((): WorldView => {
    if (wireNumbers.size === 0) {
      return painted;
    }
    return {
      ...painted,
      links: painted.links.map((link): LinkView => {
        const asked = wireNumbers.get(wireKey(link.id));
        return asked === undefined ? link : { ...link, conditional: asked };
      }),
    };
  }, [painted, wireNumbers, wireKey]);

  /**
   * One box per claim, tall enough for whichever of the two paintings needs more
   * room — a claim grows badges when an edit touched it. Reserving the taller box
   * is what lets the union be laid out once and painted twice with nothing
   * moving.
   */
  const heights = useMemo(() => {
    if (paintings === null) {
      return undefined;
    }
    const reserved = new Map<string, number>();
    for (const side of [paintings.now, paintings.before]) {
      for (const claim of side.claims) {
        reserved.set(claim.id, Math.max(reserved.get(claim.id) ?? 0, roomFor(claim)));
      }
    }
    return reserved;
  }, [paintings]);

  // The endings the edit reaches. With the engine, its own ranked rows, in its
  // own order; without it, the reachable endings in map order, and the rail
  // says on its own face which of the two it is showing.
  const rows = useMemo(
    () =>
      computed !== undefined
        ? railRows(paintings?.now ?? base, computed.change)
        : paintings === null
          ? []
          : endings(paintings.now),
    [computed, paintings, base],
  );
  const outline = useMemo(() => outlineOf(world), [world]);

  // What the branch did, said out loud for a reader who is not looking at the
  // picture. It is said twice, because the two halves arrive at different
  // moments: the shape the instant the branch opens, and the counts when the
  // engine answers. The live region is polite, so the second line waits for a
  // pause rather than cutting across the first.
  const announcement = useMemo(
    () => (paintings === null ? "" : branchAnnouncement(paintings.now, computed?.change)),
    [paintings, computed],
  );

  // One arrow's own number, asked for when the reader selects that arrow and
  // kept afterwards. It is fetched here rather than by the wire because no
  // component in this product talks to the network, and because the answer
  // belongs to the whole screen: the panel and the plate on the wire read the
  // same one.
  useEffect(() => {
    if (selection?.kind !== "wire") {
      return;
    }
    const key = wireKey(selection.id);
    if (wireNumbers.has(key)) {
      return;
    }
    let stillWanted = true;
    source
      .readConditional({ baseId: base.baseId, branch: open, linkId: selection.id })
      .then(
        (slot) => slot,
        (failure: unknown): Known<Ranged> => ({
          absence: {
            kind: "no_engine",
            words: "no engine yet",
            reason: inWords(failure),
          },
        }),
      )
      .then((slot) => {
        if (stillWanted) {
          setWireNumbers((was) => new Map(was).set(key, slot));
        }
      });
    return () => {
      stillWanted = false;
    };
  }, [selection, source, base.baseId, open, wireKey, wireNumbers]);

  // A branch has just been opened or made. Three things follow, in this order:
  // the map says out loud what the branch did, the wires arrive again in causal
  // order, and — because creating a claim moves focus to it — the keyboard lands
  // on the claim the branch added, so the view frames the thing you just made
  // rather than leaving you to hunt for it.
  useEffect(() => {
    if (shop.openId === lastBranch.current) {
      return;
    }
    lastBranch.current = shop.openId;
    setShowing("now");
    setArriving(true);
    if (paintings === null) {
      return;
    }
    const arrived = paintings.now.claims.find((claim) => claim.diff === "added");
    if (arrived !== undefined) {
      setFocused(arrived.id);
      setSelection({ kind: "claim", id: arrived.id });
      setStatus(`your edit added this claim · ${arrived.claim}`);
    }
  }, [shop.openId, paintings]);

  // The wave settles on its own clock, and on nothing else.
  //
  // **It has to be its own effect.** The one above runs again whenever the
  // picture changes — and the picture changes when the engine answers, which is
  // a moment or two after a branch is opened. A timer started up there would be
  // cleared by that second run and never started again, and the map would stay
  // mid-arrival for ever, which is to say invisible.
  useEffect(() => {
    if (!arriving) {
      return;
    }
    const settles = window.setTimeout(() => setArriving(false), WAVE_SETTLES_AFTER);
    return () => window.clearTimeout(settles);
  }, [arriving]);

  const edit = useCallback((made: Edit) => {
    setShop((was) =>
      appendEdit(was.openId === null ? forkBranch(was, "Your own branch") : was, made),
    );
  }, []);

  const keys: MapKeys = useMemo(
    () => ({
      intervene: () => {
        setDock("panel");
        setIntervening(true);
      },
      branch: () => {
        setDock("panel");
        setNaming(true);
      },
      flipWorlds: () => {
        if (paintings === null) {
          setStatus("there is nothing to flip to — no branch is open");
          return;
        }
        setShowing((was) => {
          const next = was === "now" ? "before" : "now";
          setStatus(
            next === "now"
              ? "the map with your edits"
              : "the map as it was written, with what your branch adds drawn faint",
          );
          return next;
        });
      },
      outline: () =>
        setDock((was) => {
          setOnlyColumn(null);
          return was === "outline" ? "panel" : "outline";
        }),
      panel: () => setDock((was) => (was === "away" ? "panel" : "away")),
      palette: () => setOverlay("palette"),
    }),
    [paintings],
  );

  // ⌘K, ? and Escape work wherever you are on the screen, not only on the map,
  // because two of them are how you find out what the others do.
  useEffect(() => {
    const onKey = (event: KeyboardEvent): void => {
      const target = event.target as HTMLElement | null;
      const typing =
        target?.tagName === "INPUT" ||
        target?.tagName === "TEXTAREA" ||
        target?.isContentEditable === true;
      if ((event.metaKey || event.ctrlKey) && event.key.toLowerCase() === "k") {
        event.preventDefault();
        setOverlay((was) => (was === "palette" ? null : "palette"));
        return;
      }
      if (event.key === "Escape") {
        setOverlay(null);
        setIntervening(false);
        setNaming(false);
        return;
      }
      if (event.key === "?" && !typing) {
        event.preventDefault();
        setOverlay((was) => (was === "sheet" ? null : "sheet"));
      }
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, []);

  const commands: Command[] = useMemo(() => {
    const made: Command[] = [
      {
        name: "The map as it was written",
        does: "Close the branch. Also the first row of the branch panel.",
        run: () => setShop((was) => openBranch(was, null)),
      },
      ...shop.branches.map((branch) => ({
        name: `Open the branch: ${branch.label}`,
        does: `${branch.edits.length} edits. Also a row in the branch panel.`,
        run: () => setShop((was) => openBranch(was, branch.id)),
      })),
      {
        name: "Flip between the two maps",
        does: "The same as pressing Space on the map. A hard switch, never a fade.",
        run: keys.flipWorlds,
      },
      {
        name: "Change this claim",
        does: "The six things you can do to it. The same as pressing E on the map.",
        run: keys.intervene,
      },
      {
        name: "Start a branch",
        does: "The same as pressing B on the map, and as the button in the branch panel.",
        run: keys.branch,
      },
      {
        name: "Read the map as a list",
        does: "The same as pressing O. Every claim, one sentence each.",
        run: () => {
          setOnlyColumn(null);
          setDock("outline");
        },
      },
      {
        name: "Show or hide the panel beside the map",
        does: "The same as pressing P, when you want the whole width for the map.",
        run: keys.panel,
      },
      {
        name: "Every key, on one sheet",
        does: "The same as pressing the question mark.",
        run: () => setOverlay("sheet"),
      },
      {
        name: "Back to the launchpad",
        does: "The same as the link at the top left.",
        run: onLeave,
      },
    ];
    return made;
  }, [shop.branches, keys, onLeave]);

  const pick = useCallback((id: string) => {
    setFocused(id);
    setSelection({ kind: "claim", id });
  }, []);

  return (
    <main className="page page--map">
      <header className="map-bar">
        <button className="map-bar__back" type="button" onClick={onLeave}>
          <span aria-hidden="true">←</span> Back to the launchpad
        </button>
        <h1 className="map-bar__title">{base.title}</h1>
        {open === undefined ? (
          <p className="map-bar__where">The map as it was written</p>
        ) : (
          <p className="map-bar__where">
            {/* A branch's hue rides on its name chip and its lane and nowhere
                else, and the chip always carries the branch's name — so which
                branch you are in is readable with no colour at all. */}
            <span className="map-bar__chip" data-hue={open.hue} aria-hidden="true" />
            {open.label}
            <span className="map-bar__side">
              {showing === "now" ? "with your edits" : "as it was written"}
            </span>
          </p>
        )}
        <button className="map-bar__sheet" type="button" onClick={() => setOverlay("sheet")}>
          Every key (?)
        </button>
      </header>

      {/* The map and the panel, side by side. The panel is part of the screen
          rather than something that appears over it: there are no pop-ups
          anywhere in this product, and a dialog you have to dismiss would steal
          the map that makes the detail mean anything. */}
      <div className="map-body">
        <div className="map-stage">
          <MapCanvas
            world={world}
            selection={selection}
            onSelect={setSelection}
            focused={focused}
            onFocused={setFocused}
            heights={heights}
            mapKey={`${base.baseId}:${shop.openId ?? "as-written"}`}
            keys={keys}
            onStatus={setStatus}
            onOverflow={(column) => {
              setOnlyColumn(column);
              setDock("outline");
            }}
            arriving={arriving}
          />
          {overlay === "palette" ? (
            <CommandPalette open={true} onClose={() => setOverlay(null)} commands={commands} />
          ) : null}
          {overlay === "sheet" ? (
            <ShortcutsSheet open={true} onClose={() => setOverlay(null)} />
          ) : null}
          <p className="map-status">
            <span className="map-status__mark">last key</span>
            {status}
          </p>
        </div>

        {dock === "away" ? null : (
          <aside className="dock" aria-label="The panel beside the map">
            {dock === "outline" ? (
              <Outline
                items={outline}
                onPick={pick}
                focused={focused}
                {...(onlyColumn === null
                  ? {}
                  : {
                      only: new Set(onlyColumn.claims),
                      filter:
                        `Only the claims in column ${onlyColumn.layer}, which is what the ` +
                        `collapsed tile on the map stands for. Press O for all of them.`,
                    })}
              />
            ) : (
              <>
                {intervening ? (
                  <InterventionPanel
                    world={world}
                    selection={selection}
                    onEdit={edit}
                    onClose={() => setIntervening(false)}
                  />
                ) : null}
                <BranchPanel
                  branches={shop.branches}
                  openId={shop.openId}
                  world={world}
                  onOpen={(id) => setShop((was) => openBranch(was, id))}
                  onFork={(label) => setShop((was) => forkBranch(was, label))}
                  naming={naming}
                  onNaming={setNaming}
                />
                {answer.at === "refused" ? (
                  <Refusal asking="this map" reasons={answer.reasons} />
                ) : null}
                {open === undefined ? null : (
                  <DeltaRail
                    rows={rows}
                    ranked={computed !== undefined}
                    summary={computed === undefined ? NO_SUMMARY_YET : computed.change.summary}
                  />
                )}
                <Inspector world={world} selection={selection} />
              </>
            )}
          </aside>
        )}
      </div>

      {/* What a branch did, said out loud for a reader who is not looking at the
          picture. Polite: it waits for a pause rather than cutting across
          whatever is being read. */}
      <p className="map-live" aria-live="polite">
        {announcement}
      </p>

      {/* Where every number on this map came from, and anything that is still on
          its way. There is no spinner here and never will be: a spinner says
          "wait" without saying what for, so the line says what has been asked
          and at which address, and the map keeps drawing the last answer while
          it waits. */}
      <div className="map-origin">
        <p className="map-origin__line">{world.origin}</p>
        {answer.at === "asking" ? <p className="map-origin__line">{WHILE_ASKING.reason}</p> : null}
        {answer.at === "failed" ? (
          <p className="map-origin__line">
            {`The engine did not answer, so this is the map's shape with an absence wherever a ` +
              `likelihood would have moved. ${answer.reason}`}
          </p>
        ) : null}
        {insteadOfTheEngine === null ? null : (
          <p className="map-origin__line">{insteadOfTheEngine}</p>
        )}
        {(world.warnings ?? []).map((warning) => (
          <p className="map-origin__line" key={warning}>
            {warning}
          </p>
        ))}
      </div>
    </main>
  );
}

/**
 * Where maps come from: the engine.
 *
 * Every number on the map is worked out by it, from the stored map, the branch
 * and one seed. Nothing on this screen computes a likelihood, and nothing on
 * this screen shows one the engine did not produce.
 */
const DEFAULT_SOURCE: WorldSource = new ApiWorldSource();

/**
 * Where maps come from when the engine cannot be reached.
 *
 * A map you can still read beats a blank screen. The stored example's claims,
 * arrows, dates and sources are all real and all still worth reading — what is
 * missing is the working-out, and the screen says so in a line under the map
 * rather than letting a hand-written likelihood pass for a computed one.
 */
const FALLBACK_SOURCE: WorldSource = new FixtureWorldSource();

/**
 * The line under the map when the stored example is standing in for the engine.
 *
 * @param reason What went wrong, in the sentence the failure arrived with.
 */
function insteadOfTheEngine(reason: string): string {
  return (
    `The engine did not answer, so this map is the stored example exactly as it was written: ` +
    `its claims, arrows, dates and sources are real, and its likelihoods are the illustrative ` +
    `ones somebody wrote down rather than anything worked out. ${reason}`
  );
}

/** What the screen needs. All three have defaults; all three exist so they can be swapped. */
export interface AppProps {
  /** Where maps and worlds come from. */
  readonly source?: WorldSource;
  /** Where they come from when the first one cannot answer. */
  readonly fallback?: WorldSource;
  /** How the list of stored examples is read. */
  readonly listExamples?: () => Promise<FixtureSummary[]>;
}

/** The screen. */
export function App({
  source = DEFAULT_SOURCE,
  fallback = FALLBACK_SOURCE,
  listExamples = readExampleList,
}: AppProps = {}) {
  const health = useAnswer(readHealth);
  const readiness = useAnswer(readReadiness);
  const about = useAnswer(readAbout);
  const examples = useAnswer(listExamples);

  const [screen, setScreen] = useState<Screen>({ at: "launchpad" });
  const [using, setUsing] = useState<WorldSource>(source);

  const open = useCallback(
    (id: string) => {
      setScreen({ at: "opening", id });
      /**
       * The world and the map's own branches, together: the world is what gets
       * drawn, and the branches are the edits somebody already made to it, which
       * the panel lists and the diff view folds on.
       *
       * @param from Where to ask.
       */
      const ask = (from: WorldSource) =>
        Promise.all([from.readWorld({ baseId: id }), from.readBundle(id)]);

      ask(source).then(
        ([world, bundle]) => {
          setUsing(source);
          setScreen({ at: "map", world, branches: branchesOf(bundle), insteadOfTheEngine: null });
        },
        (failure: unknown) => {
          // The engine could not answer. Rather than a blank screen, the stored
          // example — and a line under the map saying, in the failure's own
          // words, that these are not computed numbers.
          ask(fallback).then(
            ([world, bundle]) => {
              setUsing(fallback);
              setScreen({
                at: "map",
                world,
                branches: branchesOf(bundle),
                insteadOfTheEngine: insteadOfTheEngine(inWords(failure)),
              });
            },
            // Neither answered, which means the server itself is not there. That
            // is one sentence on the page, and a way back to the launchpad.
            (alsoFailed: unknown) => setScreen({ at: "failed", id, reason: inWords(alsoFailed) }),
          );
        },
      );
    },
    [source, fallback],
  );

  const toLaunchpad = useCallback(() => setScreen({ at: "launchpad" }), []);

  const readings = useMemo(
    () => [serverReading(health), modelKeyReading(readiness), versionReading(about)],
    [health, readiness, about],
  );

  if (screen.at === "map") {
    return (
      <MapScreen
        base={screen.world}
        branches={screen.branches}
        source={using}
        insteadOfTheEngine={screen.insteadOfTheEngine}
        onLeave={toLaunchpad}
      />
    );
  }

  if (screen.at !== "launchpad") {
    return (
      <main className="page page--map">
        <header className="map-bar">
          <button className="map-bar__back" type="button" onClick={toLaunchpad}>
            <span aria-hidden="true">←</span> Back to the launchpad
          </button>
          <h1 className="map-bar__title">Strait of Hormuz</h1>
        </header>

        <div className="map-waiting">
          <p className="map-waiting__line">
            {screen.at === "opening"
              ? `Reading the map from /api/fixtures/${screen.id} and asking /api/worlds to work ` +
                `its likelihoods through.`
              : screen.reason}
          </p>
        </div>
      </main>
    );
  }

  return (
    <main className="page">
      <div className="column">
        <header className="masthead">
          <h1 className="wordmark">Katalyst</h1>
          <p className="purpose">
            Type an event you think will happen. See what it would cause, step by step, ending in
            trades.
          </p>
        </header>

        <Launchpad
          examples={examples.state === "answered" ? examples.value : null}
          failure={examples.state === "failed" ? examples.reason : null}
          notLiveReason={notLiveReason(readiness)}
          onOpen={open}
        />

        <section aria-labelledby="status-heading">
          <h2 className="section-heading" id="status-heading">
            What this build can do right now
          </h2>
          <dl className="status-strip">
            {readings.map((reading) => (
              <StatusRow key={reading.label} reading={reading} />
            ))}
          </dl>
          <p className="provenance">
            Every reading above came from the server, at <code>/api/healthz</code>,{" "}
            <code>/api/readyz</code> and <code>/api/about</code>. The examples came from{" "}
            <code>/api/fixtures</code>. Nothing on this screen is written into the page.
          </p>
        </section>
      </div>
    </main>
  );
}

/**
 * The branches you have made, and the one rule that governs them: **edits are
 * appended, never rewritten.**
 *
 * A branch is a named, ordered list of edits over a base map. It holds no
 * likelihoods and no results — everything a branch shows on screen is worked out
 * from the base map plus this list, which is what makes the original safe to
 * leave untouched and what makes the whole thing replayable.
 *
 * **Why nothing here ever edits an edit in place.** The branch is the audit
 * trail. Press *Suppose this is true* on a claim, then press *Change this push*
 * on an arrow, and the two edits sit in the panel in that order — and the
 * surprising rule that a later addition outranks an earlier supposition reads as
 * a sequence rather than as a number that moved on its own. An audit trail you
 * can edit is not one. So every function below hands back a new branch whose
 * earlier edits are the very same objects, and there is no function that
 * replaces one.
 *
 * **Nothing here moves a number.** These functions build a list. Working out
 * what the list does to the map's likelihoods is the engine's job, and this half
 * of the product does none of it.
 */

import type { BranchHue, BranchView, Edit, WireBranch, WireEdit } from "./types";

/**
 * The branches on one map, and which of them is open.
 *
 * `openId` of `null` is the base world — the empty branch, the map as it was
 * written.
 */
export interface Workshop {
  /** Every branch on this map, in the order they arrived. */
  readonly branches: readonly BranchView[];
  /** Which branch is open, or `null` for the base world. */
  readonly openId: string | null;
}

/**
 * The four hues a branch may take, in the order they are handed out.
 *
 * Never amber: amber already means "the money moves down", and one hue cannot
 * mean two things. A fifth branch reuses the first hue rather than inventing a
 * fifth — every branch also carries a name chip with its label, so which branch
 * you are in is readable with no colour at all.
 */
const HUES: readonly BranchHue[] = ["violet", "teal", "rose", "slate"];

/**
 * Start from the branches a map arrived with, none of them open.
 *
 * @param branches The branches the map itself carries.
 */
export function workshopOf(branches: readonly BranchView[]): Workshop {
  return { branches, openId: null };
}

/**
 * Open a branch, or go back to the base world.
 *
 * @param shop The branches as they stand.
 * @param id The branch to open, or `null` for the base world.
 */
export function openBranch(shop: Workshop, id: string | null): Workshop {
  if (id !== null && !shop.branches.some((branch) => branch.id === id)) {
    return shop;
  }
  return { ...shop, openId: id };
}

/**
 * Make a new branch and open it.
 *
 * The new branch forks off the base map with no edits in it. It takes the next
 * hue in the list above, and its label is what the reader typed.
 *
 * @param shop The branches as they stand.
 * @param label What the reader is calling this branch. An unnamed branch is
 *   unusable once there are three of them.
 */
export function forkBranch(shop: Workshop, label: string): Workshop {
  const hue = HUES[shop.branches.length % HUES.length] ?? "violet";
  const id = `branch-${shop.branches.length + 1}`;
  const made: BranchView = {
    id,
    label,
    hue,
    edits: [],
    claims: [],
    links: [],
    // The same branch in the shape the engine is asked with. It is built here,
    // beside the drawable one, so that the two can never hold different edits:
    // there is one function below that appends to both at once and no other way
    // to change either.
    wire: { id, label, parent: null, interventions: [] },
  };
  return { branches: [...shop.branches, made], openId: made.id };
}

/**
 * One edit in the shape the server writes one, or nothing when this build
 * cannot write it down in full.
 *
 * Four of the six operations are the same few fields on both sides and cross
 * over untouched. Two do not, and both say so on screen rather than being
 * quietly dropped here:
 *
 * - **Add a claim** brings a whole claim — its wording, how it is judged, by
 *   whom, by when, what it started from — and the part of this product that
 *   drafts one is not connected. The button says so and appends nothing.
 * - **Split this claim** is not built at all. The button says so and appends
 *   nothing.
 *
 * So neither ever reaches this function from the screen. It answers for them
 * anyway, with nothing rather than with a guess, because an edit written down
 * half-way would be folded onto the map as if it were whole.
 *
 * @param edit The edit the reader just made.
 */
function asWireEdit(edit: Edit): WireEdit | null {
  switch (edit.op) {
    case "do":
      return { kind: "do", target: edit.target, value: edit.value, at: edit.at };
    case "observe":
      // Observing carries no day of its own: you can only report what has
      // already happened, and the map's window starts on its own first day.
      return { kind: "observe", target: edit.target, value: edit.value };
    case "retune":
      return { kind: "retune", link: edit.link, strength: edit.strength };
    case "believe":
      return {
        kind: "believe",
        target: edit.target,
        belief: { p: edit.belief.p, lo: edit.belief.lo, hi: edit.belief.hi, owner: "user" },
      };
    case "insert":
    case "refine":
      return null;
  }
}

/**
 * The branch with one more edit written the server's way, or nothing at all when
 * the edit cannot be written that way.
 *
 * A branch that loses its wire form keeps it lost: half a branch folded onto a
 * map is a map nobody can account for.
 */
function wireWith(branch: BranchView, edit: Edit): WireBranch | undefined {
  const written = asWireEdit(edit);
  if (branch.wire === undefined || written === null) {
    return undefined;
  }
  return { ...branch.wire, interventions: [...branch.wire.interventions, written] };
}

/**
 * Add one edit to the open branch, at the end.
 *
 * Every edit already in the branch comes through as the same object it was, so
 * that "nothing earlier was rewritten" is a property you can check by identity
 * rather than by reading fields back.
 *
 * The branch is held in two shapes at once — the one the panel reads and the
 * one the engine is asked with — and this is the only function that changes
 * either, so the two cannot come to hold different edits.
 *
 * @param shop The branches as they stand.
 * @param edit The edit the reader just made.
 * @returns The branches with the edit appended. Unchanged when no branch is
 *   open: the base map is never edited, and a branch is what an edit goes into.
 */
export function appendEdit(shop: Workshop, edit: Edit): Workshop {
  if (shop.openId === null) {
    return shop;
  }
  return {
    ...shop,
    branches: shop.branches.map((branch) =>
      branch.id === shop.openId
        ? { ...branch, edits: [...branch.edits, edit], wire: wireWith(branch, edit) }
        : branch,
    ),
  };
}

/**
 * The second world: the base map with a branch folded onto it, as far as
 * structure goes and not one step further.
 *
 * **What this builds is real, and what it leaves out is left out on purpose.**
 * Applying a branch properly means running the map's numbers again, and that is
 * the engine's work. This half of the product does none of it. So the world
 * below carries everything the branch says about *shape* — which claim arrived,
 * which arrows came with it, which arrows a supposition cut, which claims the
 * edit can reach and which it provably cannot — and, wherever a likelihood would
 * have moved, **an absence with its reason** rather than the old number left
 * lying there looking current.
 *
 * That is the honest half and it is the useful half: *here is what your edit can
 * reach, and here is what it cannot* is this product's central correctness claim
 * made visible, and it needs no arithmetic at all.
 *
 * Three rules hold it together:
 *
 * 1. **A claim your edit can reach shows its model number's absence.** The
 *    number on the base map is the base map's number; on this branch it would be
 *    something else, and nothing has worked out what. Leaving the old one on
 *    screen would be the quietest lie in the product.
 * 2. **A claim your edit provably cannot reach keeps its number, unhedged.**
 *    That is not optimism: an edit reaches only what is still joined to its
 *    subject, and everything else is identical.
 * 3. **Your own number is yours.** *My own number* writes into your own slot and
 *    is never averaged with the model's or a market's, and it is not pushed
 *    through the map — so it fills in immediately and moves nothing else.
 */

import { toMovement, toShare, toTwoFigures } from "../../components/BeliefChip";
import type {
  Absence,
  Badge,
  BranchView,
  ClaimView,
  DeltaRow,
  DiffState,
  DiffView,
  LinkView,
  Movement,
  WorldView,
} from "../../world/types";
import { badgesByClaim, standingByClaim } from "./badges";
import { readDiff } from "./diffState";
import type { Arrow } from "./reach";

/**
 * What stands where a likelihood would go on a claim this edit can reach.
 *
 * The words are the shared vocabulary's; the sentence says which number is
 * missing and who would have to work it out.
 */
export const NO_ENGINE: Absence = {
  kind: "no_engine",
  words: "no engine yet",
  reason:
    "Nothing has worked this number through the map yet. Your edit can reach this claim, so " +
    "its likelihood would move — and the part of this product that works out where to is not " +
    "connected. The old number would be the base map's, not this branch's.",
};

/**
 * Where the engine has got to with this branch.
 *
 * **Waiting is a state, not the absence of one.** The engine has been asked and
 * has not answered, or has refused, or could not be reached — and in every one
 * of those the screen owes the reader the same thing: the room the answer will
 * take, and a sentence saying why it is not there. What it must never do is
 * change size when the answer lands, so a claim the edit can reach keeps the
 * same tile in both states and only the words inside it change.
 *
 * Left out altogether means there is no engine behind this map at all — the
 * stored example standing in — and then nothing is reserved, because nothing is
 * coming.
 */
export type Engine =
  | {
      readonly at: "waiting";
      /** What stands where the numbers would be, and why. */
      readonly absence: Absence;
    }
  | {
      readonly at: "answered";
      /** The branch world, exactly as the engine built it. */
      readonly now: WorldView;
      /** What the engine says moved between the two worlds. */
      readonly change: DiffView;
    };

/** What the engine answered, or nothing when it has not. */
function answered(engine: Engine | undefined): { now: WorldView; change: DiffView } | undefined {
  return engine?.at === "answered" ? engine : undefined;
}

/**
 * What a claim's tile says about an edit, once the engine has answered.
 *
 * **Two questions, and they are not the same question.** *Did this claim's
 * number move?* is the engine's to answer, and where it has an answer — the
 * claim arrived, the claim was forced false, the number moved — its word is the
 * one the tile carries. *Can my edit reach this claim at all?* is structural,
 * the browser reads it off the branch, and the engine's `unchanged` does not
 * answer it: a claim your edit can reach whose number happened to hold still is
 * not a claim your edit cannot reach, and saying so would be telling the reader
 * the opposite of the truth.
 *
 * So the engine's word wins wherever it has one, and the structural word fills
 * the rest. Where the two can be compared they must agree, and
 * `test_the_browser_states_agree_with_the_engine` is what says so.
 *
 * @param structural What the branch alone says about this claim.
 * @param engine What the engine says about it, when the engine mentions it.
 */
export function tileState(
  structural: DiffState,
  engine: DiffView | undefined,
  id: string,
): DiffState {
  const said = engine?.claims.get(id)?.state;
  if (said === "added" || said === "killed" || said === "shifted") {
    return said;
  }
  return structural;
}

/**
 * How far this claim's number moved, as a line on its tile.
 *
 * It sits with the badges because it is one of the things the edits behind this
 * claim did to it, and because the tile already reserves room for whatever they
 * have to say. Both readings are the engine's, printed at two significant
 * figures like every other number on screen, and nothing here subtracts them.
 *
 * **Every claim the edit can reach gets this line, whether or not it moved and
 * whether or not the engine has answered yet.** That is what stops the map
 * jumping: a line that appears when the answer lands is a tile that grows when
 * the answer lands, and a tile that grows after it has been placed either shoves
 * its neighbours or sits on top of them. So the room is reserved from the moment
 * the branch opens, and only the words inside it change — the reading when the
 * claim moved, *no change* when the engine says it did not, and the reason it is
 * not there yet while the engine is being asked.
 *
 * @param moved The engine's reading of how far this claim moved, when it did.
 * @param waiting What to say instead when there is no reading: the engine's own
 *   word for where it has got to, or nothing when it has answered and the claim
 *   simply held still.
 */
function movedBadge(moved: Movement | undefined, waiting: Absence | undefined): Badge {
  if (moved === undefined) {
    return waiting === undefined
      ? {
          words: "no change",
          reason:
            "Your edit can reach this claim and the engine compared the two worlds: its " +
            "likelihood did not move by enough to report. The two numbers behind that are in " +
            "the panel beside the map.",
          movement: true,
        }
      : { words: waiting.words, reason: waiting.reason, movement: true };
  }
  const agreed = moved.sameDirection.reading;
  return {
    words: toMovement(moved.from, moved.to, moved.by, moved.way),
    reason:
      `Your edit moved this claim ${moved.way}, from ${toTwoFigures(moved.from)} to ` +
      `${toTwoFigures(moved.to)}, read on the day this claim is judged. ` +
      (agreed === undefined
        ? moved.sameDirection.absence.reason
        : `${toShare(agreed)} of the versions of the map moved the same way.`),
    movement: true,
  };
}

/**
 * Every ending the edit can reach, as the rail lists them.
 *
 * **The engine's rows first, in the engine's own order, and then the endings it
 * left out.** The engine's `rows` hold only the endings that came out `shifted`,
 * so a reader looking at that list alone cannot tell *"it did not move"* from
 * *"it is not on this map"* — and silence that could mean either is the state
 * the traceability rule exists to forbid. So the reachable endings the engine
 * left out follow, greyed and unranked, in map order, each reading **no change**
 * where the move would be.
 *
 * **Where the verdict comes from matters as much as the row.** *Did not move* is
 * read off `ClaimDiff.state`, which the engine states for every claim in either
 * world. The browser never decides it by comparing two numbers: that would be
 * the browser re-running the shifted test with its own floor and its own bar,
 * and two answers to that question is one too many.
 *
 * **A claim standing on the reader's own say-so has no move to report.** While a
 * supposition holds the claim is true in every version of the map, and the
 * engine stores a flat `1` on it so that a chain multiplied out has a factor for
 * it. No surface prints that number — and ".41 up to >.99" is that number with
 * the certainty guard in front of it. So such a row reads the word instead, the
 * same word the tile reads, and says why.
 *
 * Nothing else about a ranked row is touched: not its place in the list, not its
 * ranking, not its two columns.
 *
 * @param painted The map with the edits, as it is drawn — which is where the
 *   endings the edit can reach are known, and which claims stand on a
 *   supposition.
 * @param change What the engine answered.
 */
export function railRows(painted: WorldView, change: DiffView): readonly DeltaRow[] {
  const standing = new Map(
    painted.claims.flatMap((claim) =>
      claim.standing === undefined ? [] : [[claim.id, claim.standing] as const],
    ),
  );

  const ranked = change.rows.map((row) => {
    const word = standing.get(row.claimId);
    if (word === undefined) {
      return row;
    }
    return {
      ...row,
      move: {
        absence: {
          kind: "no_engine" as const,
          words: word.words,
          reason:
            `${word.reason} So there is no likelihood here to compare with the one this ` +
            `ending had before.`,
        },
      },
    };
  });

  const listed = new Set(ranked.map((row) => row.claimId));
  const held: DeltaRow[] = painted.claims
    .filter(
      (claim) =>
        (claim.kind === "market" || claim.kind === "not_tradeable") &&
        claim.diff !== undefined &&
        claim.diff !== "untouched" &&
        !listed.has(claim.id) &&
        change.claims.get(claim.id)?.state === "unchanged",
    )
    .map((claim) => ({
      claimId: claim.id,
      label: claim.claim,
      kind: claim.kind,
      move: {
        absence: {
          kind: "no_engine" as const,
          words: "no change",
          reason:
            "This ending is on the map and your edit did not move it: the engine compared the " +
            "two worlds and said so itself. It is listed so that holding still cannot be " +
            "mistaken for not being here.",
        },
      },
      rangeWidth: {
        absence: {
          kind: "no_engine" as const,
          words: "—",
          reason: "How firm a number is only says something about a number that moved.",
        },
      },
      agreement: {
        absence: {
          kind: "no_engine" as const,
          words: "—",
          reason:
            "Whether the versions of the map agreed on a direction only says something about a " +
            "claim that had a direction.",
        },
      },
      noChange: true,
    }));

  return [...ranked, ...held];
}

/**
 * The two paintings of one diff: the map with your edits, and the map as it was.
 *
 * **One layout, two paintings.** Both worlds hold exactly the same claims and the
 * same arrows, in the same order — so the union is laid out once and nothing
 * moves when you flip between them. What differs is what each tile *says*: in
 * the map as it was, the strike is a ghost and every number is the one the map
 * was written with; in the map with your edits, the strike is a real tile with
 * an accent ring and every number your edit could move reads its absence.
 *
 * A claim or an arrow that only one of the two has is drawn in the other as a
 * **ghost** — faint, in the same place — rather than vanishing. A tile that
 * disappeared would be a change you could only catch by remembering where it had
 * been.
 *
 * @param base The base world, exactly as the map was written.
 * @param branch The branch to fold onto it.
 * @param engine Where the engine has got to with this branch. Left out, there
 *   is no engine behind this map at all and every likelihood the edit could move
 *   reads its absence for good.
 */
export function bothPaintings(
  base: WorldView,
  branch: BranchView,
  engine?: Engine,
): { now: WorldView; before: WorldView } {
  const now = branchWorld(base, branch, engine);
  const added = new Set(branch.claims.map((claim) => claim.id));
  const addedArrows = new Set(branch.links.map((link) => link.id));
  return {
    now: {
      ...now,
      // An arrow a supposition cut is not in the map with your edits: supposing a
      // claim says "do not tell me what caused it". It is still drawn, faint, in
      // the place it was.
      links: now.links.map((link) => ({ ...link, ghost: link.change === "cut" })),
    },
    before: {
      ...base,
      claims: [
        ...base.claims,
        ...branch.claims.map((claim) => ({ ...claim, ghost: true, diff: "added" as const })),
      ],
      links: [
        ...base.links,
        ...branch.links.map((link) => ({ ...link, ghost: true, change: "added" as const })),
      ],
      origin:
        `${base.origin} This is the map as it was written, with the ` +
        `${addedArrows.size === 1 ? "one arrow" : `${addedArrows.size} arrows`} and the ` +
        `${added.size === 1 ? "claim" : "claims"} your branch adds drawn faint, in the places ` +
        `they take on the other side of the switch — so that flipping between the two moves ` +
        `nothing.`,
    },
  };
}

/** Every arrow, as working out what an edit reaches needs it. */
function asArrows(links: readonly LinkView[]): Arrow[] {
  return links.map((link) => ({
    id: link.id,
    source: link.source,
    target: link.target,
    reflexive: link.reflexive,
  }));
}

/**
 * Fold a branch onto a base world and hand back the second world.
 *
 * Both worlds are drawn in one coordinate space afterwards, so nothing here
 * moves a claim: the union of the two maps is laid out once and painted twice.
 *
 * @param base The base world, exactly as the map was written.
 * @param branch The branch: its edits in order, and whatever whole claims and
 *   arrows the map supplied for them.
 * @param engine Where the engine has got to. Once it has answered, its claims
 *   carry the computed likelihoods, its badges are read off the world, and its
 *   difference says which claims moved. While it is still being asked, the room
 *   those answers will take is reserved and says why it is empty.
 */
export function branchWorld(base: WorldView, branch: BranchView, engine?: Engine): WorldView {
  const computed = answered(engine);
  // The claims and arrows to draw. With the engine, they are the map its edits
  // left behind — which already holds whatever the branch added. Without it,
  // the base map plus whatever whole claims and arrows the branch supplied.
  const claims = computed === undefined ? [...base.claims, ...branch.claims] : computed.now.claims;
  const links = computed === undefined ? [...base.links, ...branch.links] : computed.now.links;
  const diff = readDiff(
    claims.map((claim) => claim.id),
    asArrows(links),
    branch.edits,
  );

  const words = new Map(claims.map((claim) => [claim.id, claim.claim]));
  for (const edit of branch.edits) {
    if (edit.op === "insert" && !words.has(edit.claimId)) {
      words.set(edit.claimId, edit.words);
    }
  }
  // What the tiles say about the edits behind them. With the engine, the world
  // carries every value an edit fixed and every supposition a later edit
  // undermined, and the badges were read off it; without it they are derived
  // here from the branch. One line, one derivation, whichever it is.
  const derived = badgesByClaim(branch.edits, {
    words,
    arrows: new Map(
      branch.links.map((link) => [
        link.id,
        { source: link.source, mode: link.mode, strength: link.strength },
      ]),
    ),
  });
  const badges =
    computed === undefined
      ? derived
      : new Map(computed.now.claims.map((claim) => [claim.id, [...(claim.badges ?? [])]]));
  const standing =
    computed === undefined
      ? standingByClaim(branch.edits, derived)
      : new Map(
          computed.now.claims.flatMap((claim) =>
            claim.standing === undefined ? [] : [[claim.id, claim.standing] as const],
          ),
        );

  // Your own numbers, from every **My own number** edit on this branch. A later
  // one on the same claim replaces an earlier one on screen; both stay in the
  // branch, in order, because the branch is the audit trail.
  const yours = new Map(
    branch.edits.flatMap((edit) => (edit.op === "believe" ? [[edit.target, edit.belief]] : [])),
  );

  return {
    ...base,
    ...(computed === undefined
      ? {}
      : {
          // How the engine was run, so the chip can say whether its range was
          // computed and the line under the map can name the seed.
          versions: computed.now.versions,
          worldsPerVersion: computed.now.worldsPerVersion,
          seed: computed.now.seed,
          warnings: computed.now.warnings,
        }),
    branch,
    claims: claims.map((claim): ClaimView => {
      const ownNumber = yours.get(claim.id);
      const structural = diff.states.get(claim.id) ?? "untouched";
      const state = tileState(structural, computed?.change, claim.id);
      // How far the number moved — unless the claim is standing on the reader's
      // own say-so, in which case there is no number to have moved to. While a
      // supposition holds the claim is true in every version of the map, and the
      // engine stores a flat 1 on it so that a chain has a factor to multiply;
      // **no surface prints that number**, and a reading of ".40 up to >.99" is
      // that number wearing the certainty guard's clothes. The badge pair says
      // *Supposed · Oct 1* instead, which is what actually happened.
      const supposed = standing.get(claim.id) !== undefined;
      // What the engine read on this claim: the two numbers, which way they
      // went, and whether the move came from nothing but the observation
      // changing how much each version counts. It is carried for **every** claim
      // the engine read, not only the ones it calls `shifted` — a claim can move
      // a hair and still come out unchanged, and when it did so purely by
      // reweighting the panel has a sentence for exactly that.
      const moved = supposed ? undefined : computed?.change.claims.get(claim.id)?.moved;
      // Which tiles reserve a line for how far their number moved: the ones the
      // edit can reach, and only those. A claim it added, one it forced false
      // and one it cannot reach have nothing to say there, and a claim standing
      // on the reader's say-so says the word instead. **The same set in both
      // states**, so the tile is the same size before and after the answer.
      const reserves = (state === "downstream" || state === "shifted") && !supposed;
      return {
        ...claim,
        diff: state,
        moved,
        badges: [
          ...(badges.get(claim.id) ?? []),
          // The tile's line reads the move only when the engine calls the claim
          // shifted. A claim that moved a hair and came out unchanged reads *no
          // change*, which is the engine's own verdict; the two numbers behind
          // it are one click away in the panel.
          ...(reserves && engine !== undefined
            ? [
                movedBadge(
                  state === "shifted" ? moved : undefined,
                  engine.at === "waiting" ? engine.absence : undefined,
                ),
              ]
            : []),
        ],
        standing: standing.get(claim.id),
        beliefs: {
          ...claim.beliefs,
          // With the engine's answer, the model's number on this claim is the
          // engine's own for this branch and stays exactly as it came. Without
          // it, a claim the edit can reach shows an absence — the engine's own
          // word for where it got to when there is one, so that a branch it
          // refused says *that* rather than "no engine yet". The number on
          // screen would otherwise be the base map's, not this branch's, and
          // leaving it there would be the quietest lie in the product.
          model:
            computed === undefined && diff.canMove.has(claim.id)
              ? { absence: engine?.at === "waiting" ? engine.absence : NO_ENGINE }
              : claim.beliefs.model,
          user: ownNumber === undefined ? claim.beliefs.user : { reading: ownNumber },
        },
        // A whole chain's likelihood is multiplied out where the map's numbers
        // are worked out, and never here. It was an absence on the base world
        // and it is the same absence on this one.
        pathProduct: claim.pathProduct,
      };
    }),
    links: links.map(
      (link): LinkView => ({
        ...link,
        change: diff.addedLinks.has(link.id)
          ? "added"
          : diff.cutLinks.has(link.id)
            ? "cut"
            : diff.retunedLinks.has(link.id)
              ? "retuned"
              : undefined,
      }),
    ),
    origin:
      computed === undefined
        ? `${base.origin} This branch — "${branch.label}" — is the same map with ` +
          `${branch.edits.length === 1 ? "one edit" : `${branch.edits.length} edits`} folded ` +
          `onto it. What you can see of it is shape: which claim arrived, which arrows came ` +
          `with it, and which claims those arrows can reach. Every likelihood a branch would ` +
          `move reads its absence, because nothing has worked one out.`
        : computed.now.origin,
  };
}

/**
 * Turning the server's own shapes into the shapes the canvas draws.
 *
 * Two sources read the server: the one that reads the stored example as it was
 * written, and the one that asks the engine to work a branch through. Both of
 * them turn the same claims, the same arrows and the same published items into
 * the same tiles and wires, so that work is written once, here, and neither can
 * drift from the other.
 *
 * **There is no arithmetic anywhere in this file.** A likelihood is read from
 * the server and carried, untouched and at full precision, to the component that
 * prints it. Rounding is a display decision and is made once, in the chip.
 *
 * **Nothing here invents a number.** Every slot that has no likelihood in it
 * gets an absence and the sentence saying why, and there is no path through any
 * function below that hands back a blank, a zero or a stand-in.
 */

import type { components } from "../api/schema";
import type {
  Absence,
  AbsenceKind,
  BaseRateView,
  ClaimView,
  EvidenceClipping,
  Known,
  LinkView,
  Ranged,
  SourceView,
} from "./types";

type FixtureBundle = components["schemas"]["FixtureBundle"];
type Proposition = components["schemas"]["Proposition"];
type Belief = components["schemas"]["Belief"];
type Evidence = components["schemas"]["Evidence"];
type Source = components["schemas"]["Source"];
type Link = components["schemas"]["Link"];

/**
 * The seed every question about one map is asked with.
 *
 * A world can always be rebuilt from three things — the map, the branch and the
 * seed — so the seed has to be the same on every visit, or the same map would
 * read differently twice in a row. It is read off the map's own date rather than
 * picked: the stored example is set on 2026-10-01, so the seed is 20261001. It
 * is printed under the map, beside the map's address, so that anybody can ask
 * the engine the same question and get the same answer.
 *
 * A seed is an input, not a reading. Nothing on screen is a number this
 * produced; it decides which of two thousand versions of the map get tried.
 *
 * @param bundle The stored example in full.
 * @returns The map's own date with its dashes taken out, as a whole number.
 */
export function seedFor(bundle: FixtureBundle): number {
  return Number(bundle.fixture_date.replaceAll("-", ""));
}

/**
 * Turn a likelihood from the server into a filled slot, unchanged.
 *
 * The three numbers are copied across at full precision. Rounding is a display
 * decision and is made once, in the chip that prints them.
 */
export function filled(belief: Belief): Known<Ranged> {
  return { reading: { p: belief.p, lo: belief.lo, hi: belief.hi } };
}

/** Turn "there is no number here" into the words and the reason for them. */
export function missing(kind: AbsenceKind, words: string, reason: string): Known<Ranged> {
  const absence: Absence = { kind, words, reason };
  return { absence };
}

/**
 * The single letter that stands for a publication, taken from the host name in
 * its own web address.
 *
 * `https://www.bbc.com/news/...` gives `B`. A leading `www.` is dropped first,
 * because every publication has one and it would make every monogram a `W`.
 *
 * A letter rather than the publication's own icon, deliberately: an icon is a
 * request to somebody else's server, and this app draws its first frame without
 * making one.
 */
export function monogramFor(url: string): { monogram: string; host: string } {
  let host: string;
  try {
    host = new URL(url).hostname;
  } catch {
    // An address we cannot read is not a crash. The clipping still has a line
    // to show, and the mark beside it says plainly that there is no host name.
    return { monogram: "?", host: "an address we could not read" };
  }
  const withoutWww = host.startsWith("www.") ? host.slice(4) : host;
  const first = withoutWww.slice(0, 1).toUpperCase();
  return { monogram: first === "" ? "?" : first, host: withoutWww };
}

/** Turn one published item into the clipping a tile shows. */
function clipping(evidence: Evidence): EvidenceClipping {
  const { monogram, host } = monogramFor(evidence.url);
  return {
    line: evidence.claim,
    monogram,
    host,
    direction: evidence.direction,
    url: evidence.url,
  };
}

/**
 * Turn one item behind an arrow into the source the panel prints.
 *
 * `retrieved` is the day *our own retrieval step* pulled the page down. It is
 * absent whenever a person typed the address in by hand, which is the case for
 * every source in the stored example — and the panel says that in words rather
 * than printing a day nobody fetched anything on.
 */
function source(item: Source): SourceView {
  const { host } = monogramFor(item.url);
  return {
    url: item.url,
    title: item.title,
    host,
    retrieved:
      item.retrieved === null || item.retrieved === undefined
        ? {
            absence: {
              kind: "not_said",
              words: "—",
              reason: "nobody fetched this; a person put the address in by hand",
            },
          }
        : { day: item.retrieved },
  };
}

/**
 * How often this kind of thing has happened before — or, when the map records
 * no such count, the sentence saying so.
 *
 * The count is printed as `7 of 9` and never as a rate. Dividing one by the
 * other would be this half of the product doing arithmetic on the map's
 * numbers, and it would also quietly claim that seven-in-nine is the answer,
 * which is exactly what a prior is for and exactly what it is not.
 */
function baseRate(
  proposition: Proposition,
): { readonly reading: BaseRateView } | { readonly absence: Absence } {
  const stored = proposition.base_rate;
  if (stored === null || stored === undefined) {
    return {
      absence: {
        kind: "not_said",
        words: "—",
        reason: "no reference class recorded for this claim",
      },
    };
  }
  return {
    reading: {
      referenceClass: stored.reference_class,
      k: stored.k,
      n: stored.n,
      sources: stored.sources.map((url) => source({ url, title: url, retrieved: null })),
    },
  };
}

/**
 * Why a claim has no market number, in the words the shared vocabulary settles.
 *
 * These three sentences are written here and nowhere else, so that the chip,
 * the tile and the panel beside the map cannot drift apart about what "no
 * market" means. `spec/vocabulary.md` is their source; change it there first
 * and then here.
 *
 * A claim that *ends* the map without an instrument is the exception, and it is
 * handled below: that one has a reason of its own, written down when the map
 * was made, and it is a finding rather than a fact about our plumbing.
 */
const NO_MARKET_REASON: Record<"market" | "event" | "hypothesis", string> = {
  market: "no venue quotes this claim; what you would trade is on the payoff",
  event: "no venue quotes this claim",
  hypothesis: "no venue quotes this claim",
};

/** Why this claim has no market number. */
function marketAbsence(proposition: Proposition): Known<Ranged> {
  if (proposition.kind === "not_tradeable") {
    // A dead end says why it is a dead end, in the map's own words. This is the
    // one reason a tile prints for itself, because it is an answer rather than
    // an apology.
    return missing(
      "no_market",
      "no market",
      proposition.not_tradeable_reason ?? NO_MARKET_REASON.event,
    );
  }
  return missing("no_market", "no market", NO_MARKET_REASON[proposition.kind]);
}

/**
 * What stands where a chain's multiplied-out likelihood would go.
 *
 * **A world does not carry one yet.** It holds a likelihood for every claim and
 * a series for every day, and nothing anywhere multiplies a route's steps
 * together. The engine will carry it; until it does the slot says so, because
 * working it out here would put a second answer on the map beside the engine's.
 */
export const NO_PATH_PRODUCT: Absence = {
  kind: "no_engine",
  words: "no engine yet",
  reason:
    "Nothing has multiplied this chain out. The likelihood of a whole route is worked out " +
    "where the map's numbers are, and the engine does not carry one yet.",
};

/**
 * Turn one claim from the server into the claim a tile draws.
 *
 * Every likelihood on it is the server's own. What the *model* thinks may be
 * replaced afterwards by a computed world's answer for the same claim; nothing
 * else is ever replaced.
 *
 * @param proposition The claim exactly as the server serves it.
 */
export function toClaim(proposition: Proposition): ClaimView {
  const beliefs = proposition.beliefs;
  return {
    id: proposition.id,
    claim: proposition.claim,
    kind: proposition.kind,
    resolvesBy: proposition.resolution.by,
    resolutionSource: proposition.resolution.source,
    resolutionCriteria: proposition.resolution.criteria,
    prior: { p: proposition.prior.p, lo: proposition.prior.lo, hi: proposition.prior.hi },
    baseRate: baseRate(proposition),
    beliefs: {
      model: filled(beliefs.model),
      user: beliefs.user
        ? filled(beliefs.user)
        : missing("not_said", "—", "You have not put your own number on this claim yet."),
      market: beliefs.market ? filled(beliefs.market) : marketAbsence(proposition),
    },
    // At most two clippings on a tile; every one of them in the panel beside
    // the map, where there is room to read them.
    evidence: proposition.evidence.slice(0, 2).map(clipping),
    evidenceInFull: proposition.evidence.map(clipping),
    pathProduct: { absence: NO_PATH_PRODUCT },
  };
}

/**
 * What stands where an arrow's own number would go before anything has asked
 * for it.
 *
 * The likelihood of this arrow's target with its cause supposed true costs a
 * whole extra run of the map, so it is worked out one arrow at a time, when a
 * reader asks about that arrow and not before.
 */
export const NOT_ASKED_FOR_YET: Absence = {
  kind: "no_engine",
  words: "no engine yet",
  reason:
    "Nothing has worked this number through the map yet. The likelihood with this arrow's " +
    "cause supposed true costs a whole extra run of the map, so it is worked out one arrow " +
    "at a time — select this arrow and it is asked for.",
};

/** Turn one arrow from the server into the arrow a wire draws. */
export function toLink(link: Link): LinkView {
  return {
    id: link.id,
    source: link.source,
    target: link.target,
    mode: link.mode,
    // Carried across at full precision and never touched. The wire compares it
    // against four fixed widths and five fixed bands of words; nothing adds it
    // to anything.
    strength: link.strength,
    lag: link.lag,
    shape: link.shape,
    halfLife: link.half_life ?? null,
    rationale: link.rationale,
    sources: link.sources.map(source),
    provenance: link.provenance,
    conditional: { absence: NOT_ASKED_FOR_YET },
    reflexive: link.reflexive,
  };
}

