1	/**
2	 * One likelihood, with the range that says how sure we are of it — or, when
3	 * there is no likelihood, the absence and the reason for it.
4	 *
5	 * This is the smallest component in the product and the one carrying the most
6	 * of its honesty rule, so it is worth reading in full.
7	 *
8	 * **Two significant figures and the range, always.** A likelihood is printed as
9	 * `.35` and never as `.348` — a third figure claims an accuracy nobody has —
10	 * and it is never printed without the range under it. The rounding happens
11	 * here, once, at the moment of display; everything upstream carries the number
12	 * at full precision so that nothing is rounded twice.
13	 *
14	 * **What the range means, said out loud.** It is *how sure we are of the
15	 * number*, not how much the world can move. How much the world can move is
16	 * already inside the likelihood itself. That distinction is not a footnote: a
17	 * reader who takes a wide range to mean a volatile event has been misled by the
18	 * interface, so the model chip says which it is in its own label and spells it
19	 * out in full when you look at it.
20	 *
21	 * **An absent number is an absence, never a blank.** There is no path through
22	 * this component that prints nothing, prints a zero, or prints a stand-in. A
23	 * slot with no number shows the words for its absence and carries the reason
24	 * for it. A claim standing on the reader's own say-so shows the word — *Supposed
25	 * · Oct 1* — because while it is supposed it is true in every simulated world
26	 * and there is no number to show.
27	 */
28	
29	import { useId, useState } from "react";
30	import { type LikelihoodStep, likelihoodStep } from "../graph/wires/encodings";
31	import type { BeliefOwner, Known, Ranged, Standing } from "../world";
32	import "./beliefChip.css";
33	
34	/**
35	 * A number at two significant figures, split into its digits and where the point
36	 * sits — or nothing at all, for a number there is no sense in printing.
37	 *
38	 * The value it stands for is `figures × 10^(exponent − 1)`: `.35` is 35 and −1,
39	 * `.0035` is 35 and −3, `1.0` is 10 and 0.
40	 *
41	 * **Why it does not use the obvious shortcut.** A computer stores .995 as
42	 * 0.99499999999999999556, so asking it directly for two figures gives `.99` —
43	 * and .995 is precisely the case the certainty guard exists for. So the rounding
44	 * is done on the number's own decimal digits instead: the shortest decimal that
45	 * reads back as this exact number, its point shifted by counting rather than by
46	 * multiplying, and then rounded half-up. `.995` shifts to exactly 99.5, which
47	 * rounds to 100, which carries to 1.
48	 *
49	 * @param value Any number from 0 up.
50	 */
51	function twoFigures(value: number): { figures: number; exponent: number } | null {
52	  if (!Number.isFinite(value) || value <= 0) {
53	    return null;
54	  }
55	  const [mantissa = "0", place = "0"] = value.toExponential().split("e");
56	  let exponent = Number(place);
57	  // The two figures, as a whole number from 10 to 99.
58	  let figures = Math.round(Number(`${mantissa}e1`));
59	  if (figures >= 100) {
60	    // Rounding up carried into the next place: .0999 becomes .10, not .100.
61	    figures = 10;
62	    exponent += 1;
63	  }
64	  return { figures, exponent };
65	}
66	
67	/**
68	 * Write those two figures out.
69	 *
70	 * Both digits are always printed — `.060` keeps its trailing nought, because
71	 * dropping it would claim less precision than we have, and "two figures except
72	 * when the second is a nought" would be a second rule for one ugly case.
73	 */
74	function written({ figures, exponent }: { figures: number; exponent: number }): string {
75	  if (exponent < 0) {
76	    return `.${"0".repeat(-exponent - 1)}${figures}`;
77	  }
78	  const digits = `${figures}`;
79	  // A number at or above one: the point sits inside or after the two figures.
80	  return exponent === 0 ? `${digits[0]}.${digits[1]}` : digits + "0".repeat(exponent - 1);
81	}
82	
83	/**
84	 * Print a **likelihood** — or an end of the range around one, which is a
85	 * likelihood too — the way this product prints one.
86	 *
87	 * **A likelihood, and only a likelihood.** How far a number moved and how wide a
88	 * band is are measured on the same scale and are not likelihoods; they take
89	 * `toSize` below, and the difference is the guard.
90	 *
91	 * **Two significant figures.** A likelihood is between zero and one, so the
92	 * leading zero is dropped: `.35`, not `0.35`. Both figures are always printed.
93	 *
94	 * **It never prints a certainty, at either end.** A likelihood of 1 says the
95	 * thing cannot fail and a likelihood of 0 says it cannot happen, and nothing on
96	 * this map is entitled to either. So the guard is applied to the number **as it
97	 * would print**: what two figures would print at or above `1.0` prints `>.99`,
98	 * and what they would print below `.010` prints `<.01` (Kent, 2026-09-20, G10).
99	 * `.0099` is below the line and reads `<.01`; `.010` is on it and reads `.010`.
100	 *
101	 * **This rule is written twice and the two copies must move together.** The
102	 * engine writes the same numbers into the one-line summary it carries, in
103	 * `backend/src/katalyst/domain/diff.py::_two_figures`. A screen and a sentence
104	 * that round the same number differently are two answers to one question.
105	 *
106	 * @param value A likelihood, at full precision.
107	 * @returns The number as it is shown on screen.
108	 */
109	export function toTwoFigures(value: number): string {
110	  if (!Number.isFinite(value) || value <= 0) {
111	    return "<.01";
112	  }
113	  if (value >= 1) {
114	    return ">.99";
115	  }
116	  const rounded = twoFigures(value);
117	  if (rounded === null) {
118	    return "<.01";
119	  }
120	  // Read off the printed value rather than the one that came in. Two figures
121	  // put the point one place after them, so anything below a hundredth lands at
122	  // an exponent under −2 — and `.00996` rounds up to `.010` and stays.
123	  if (rounded.exponent >= 0) {
124	    return ">.99";
125	  }
126	  if (rounded.exponent < -2) {
127	    return "<.01";
128	  }
129	  return written(rounded);
130	}
131	
132	/**
133	 * Print a **size** on the likelihood scale: how far a number moved, or how wide
134	 * a band is.
135	 *
136	 * **A size is not a likelihood, and it takes no guard.** `<.01` on a likelihood
137	 * says "nothing here, but we are not calling it impossible" — a claim about the
138	 * world. A move of nine thousandths is not a claim about the world at all; it is
139	 * a measurement, and rounding it away to `<.01` would throw out the only thing
140	 * the reader came for. So two significant figures, however small: `.0090`,
141	 * `.0035`, `.00012` (Kent, 2026-09-20, G10).
142	 *
143	 * The other end takes no guard either: a move of exactly one is a real move, and
144	 * it prints `1.0`.
145	 *
146	 * @param value A distance between two likelihoods, at full precision. Its sign
147	 *   is said in words elsewhere, so pass its size.
148	 */
149	export function toSize(value: number): string {
150	  const rounded = twoFigures(Math.abs(value));
151	  return rounded === null ? "0" : written(rounded);
152	}
153	
154	/** The chevron and the word each direction goes by. Neither is a colour. */
155	const WAY = {
156	  up: { chevron: "▲", word: "up" },
157	  down: { chevron: "▼", word: "down" },
158	} as const;
159	
160	/**
161	 * How far a number moved, in the one form every surface prints it in.
162	 *
163	 * **Never a chevron between two readings that print the same.** Two figures is
164	 * the whole of what this product shows, and a move smaller than the second
165	 * figure leaves the before and the after printing identically — `.36 ▲ .36`,
166	 * which says "it went up" and "it is where it was" in the same breath and reads
167	 * as a fault in the tool. So where the two readings differ the row is the pair
168	 * with the chevron between them, and where they do not it is the one reading and
169	 * the size of the move in words: `.36 · up by .0090`.
170	 *
171	 * The size is the engine's own, at two significant figures **and no guard**: a
172	 * move of nine thousandths is a measurement, not a claim about the world, and
173	 * rounding it away to `<.01` would throw out the only thing the reader came
174	 * for (Kent, 2026-09-20, G10).
175	 *
176	 * @param from The first world's likelihood, at full precision.
177	 * @param to The second world's likelihood, at full precision.
178	 * @param by How far it moved, as the engine reported it. Its sign is already
179	 *   said by `way`, so only its size is printed.
180	 * @param way Which way it went, as the engine read it.
181	 */
182	export function toMovement(from: number, to: number, by: number, way: "up" | "down"): string {
183	  const before = toTwoFigures(from);
184	  const after = toTwoFigures(to);
185	  if (before !== after) {
186	    return `${before} ${WAY[way].chevron} ${after}`;
187	  }
188	  // Nothing moved at all — the engine's own difference is zero — so there is no
189	  // direction to name. "up by 0" would be a direction invented for a number that
190	  // has none.
191	  if (by === 0) {
192	    return after;
193	  }
194	  return `${after} · ${WAY[way].word} by ${toSize(by)}`;
195	}
196	
197	/**
198	 * Print a range the way this product prints one: `.22–.50`.
199	 *
200	 * Both ends are likelihoods, so both take the guard: a band whose bottom end
201	 * sits under a hundredth reads `<.01–.03`, which says the low end is small
202	 * without calling it impossible.
203	 *
204	 * The dash is an en dash, the one used for a span between two numbers.
205	 */
206	export function toRange(lo: number, hi: number): string {
207	  return `${toTwoFigures(lo)}–${toTwoFigures(hi)}`;
208	}
209	
210	/**
211	 * Print a share of something counted — *how many of the two thousand versions
212	 * of the map moved the same way* — as a whole percentage.
213	 *
214	 * A share is not a likelihood. It is a count of things that happened divided by
215	 * how many there were, so a hundred per cent really can mean *every one of
216	 * them*, and printing `>.99` over it would hide a fact the machine actually
217	 * counted. So the only guard here is the one that stops rounding from inventing
218	 * unanimity: a share that is not quite all of them never prints as all of them.
219	 *
220	 * Two figures, like everything else on screen: `97%`, never `96.63%`.
221	 *
222	 * @param share A share from 0 to 1, at full precision.
223	 */
224	export function toShare(share: number): string {
225	  if (!Number.isFinite(share)) {
226	    return "—";
227	  }
228	  const whole = Math.round(share * 100);
229	  if (whole >= 100 && share < 1) {
230	    return ">99%";
231	  }
232	  if (whole <= 0 && share > 0) {
233	    return "<1%";
234	  }
235	  return `${whole}%`;
236	}
237	
238	/**
239	 * The whole reading, in the form a sentence would use: `.35 (.22–.50)`.
240	 *
241	 * This is what the chip is called when it is read aloud, and what the tile uses
242	 * when it needs the reading inside a longer sentence.
243	 */
244	export function toReading(p: number, lo: number, hi: number): string {
245	  return `${toTwoFigures(p)} (${toRange(lo, hi)})`;
246	}
247	
248	/** The word each owner is called by on screen. */
249	const OWNER_WORDS: Record<BeliefOwner, string> = {
250	  model: "model",
251	  user: "user",
252	  market: "market",
253	};
254	
255	/**
256	 * The note a chip opens when you look at it: one label, one sentence.
257	 *
258	 * It is not a pop-up. It is a shelf that slides out from the bottom edge of the
259	 * tile, drawn on the tile's own surface, and it needs no dismissing — look
260	 * away, or move the keyboard on, and it closes itself.
261	 */
262	interface Note {
263	  /** The chip's label, printed as the first line of the shelf. */
264	  readonly label: string;
265	  /** The sentence under it. */
266	  readonly sentence: string;
267	}
268	
269	/** Group a count in thousands the way the sentence below writes it: `2 000`. */
270	function inThousands(count: number): string {
271	  return count.toLocaleString("en-GB").replace(/,/g, " ");
272	}
273	
274	/**
275	 * What the model chip says about itself — and there are two answers, because
276	 * there are two different things a range can be.
277	 *
278	 * **When a world computed these numbers**, the range came out of running the
279	 * map many times over, each run a coherent set of numbers the model would have
280	 * stood behind, and the sentence says so and then admits in its last clause
281	 * that nobody has checked the claim against anything that resolved.
282	 *
283	 * **When nothing computed them** — which is every number in this build, because
284	 * the engine's route does not exist yet — the range is what whoever wrote the
285	 * number down said about how sure they were. Saying "across 2 000 versions of
286	 * this map" over a number nobody ran through a map would be the plainest kind
287	 * of lie this product can tell, so it says the other thing instead.
288	 *
289	 * The chip picks between them by one fact: whether the world it is drawing
290	 * reports how many versions were run. Nothing else changes when the engine
291	 * lands.
292	 */
293	function modelNote(p: number, lo: number, hi: number, versions: number | undefined): Note {
294	  if (versions === undefined) {
295	    return {
296	      label: "stated range · not computed",
297	      sentence:
298	        "This range is stated, not computed — it says how sure the elicitation was. " +
299	        "Nothing has worked this number through the map yet.",
300	    };
301	  }
302	  return {
303	    label:
304	      `model interval, uncalibrated · how sure we are of ${toTwoFigures(p)} — ` +
305	      `not how much the world can move`,
306	    sentence:
307	      `Across ${inThousands(versions)} versions of this map — each one a set of numbers this ` +
308	      `model would have stood behind — the answer landed between ${toTwoFigures(lo)} and ` +
309	      `${toTwoFigures(hi)} eight times in ten. Nobody has checked whether that 8-in-10 holds ` +
310	      `up; no claim on this map has resolved yet.`,
311	  };
312	}
313	
314	/** What the reader's own chip says about itself. */
315	function userNote(p: number, lo: number, hi: number): Note {
316	  return {
317	    label: `your own number · ${toReading(p, lo, hi)}`,
318	    sentence:
319	      "This is the number you gave. It sits beside the model's and the market's and is " +
320	      "never averaged with either of them.",
321	  };
322	}
323	
324	/** What a market chip says about itself. */
325	function marketNote(lo: number, hi: number): Note {
326	  return {
327	    label: "market, as a venue is quoting it",
328	    sentence:
329	      `The likelihood is the middle of the best bid and the best offer; the range, ` +
330	      `${toRange(lo, hi)}, is the spread between them. It is what somebody will trade this ` +
331	      `claim at, not an opinion about it.`,
332	  };
333	}
334	
335	/** Work out the three lines a chip shows, and the note behind it. */
336	function readChip(
337	  owner: BeliefOwner,
338	  slot: Known<Ranged>,
339	  standing: Standing | undefined,
340	  versions: number | undefined,
341	): {
342	  reading: string;
343	  under: string | null;
344	  spoken: string;
345	  note: Note;
346	  numeric: boolean;
347	  step: LikelihoodStep | null;
348	} {
349	  // A claim the reader has supposed true is true in every simulated world, so
350	  // the chip shows the word rather than a number. Inventing one — .98, or 1.0 —
351	  // would invite the reader to wonder about the other two per cent of a thing
352	  // they themselves declared settled.
353	  if (standing !== undefined) {
354	    return {
355	      reading: standing.words,
356	      under: null,
357	      spoken: `${OWNER_WORDS[owner]}: ${standing.words}`,
358	      note: { label: standing.words, sentence: standing.reason },
359	      numeric: false,
360	      step: null,
361	    };
362	  }
363	
364	  if (slot.reading === undefined) {
365	    const absence = slot.absence;
366	    return {
367	      reading: absence.words,
368	      // The reader's own empty slot says what to do about it; every other
369	      // absence keeps its sentence for the shelf, where there is room for it.
370	      under: owner === "user" ? "add yours" : null,
371	      spoken: `${OWNER_WORDS[owner]}: ${absence.words}. ${absence.reason}`,
372	      note: { label: absence.words, sentence: absence.reason },
373	      numeric: false,
374	      step: null,
375	    };
376	  }
377	
378	  const { p, lo, hi } = slot.reading;
379	  const note =
380	    owner === "model"
381	      ? modelNote(p, lo, hi, versions)
382	      : owner === "user"
383	        ? userNote(p, lo, hi)
384	        : marketNote(lo, hi);
385	  return {
386	    reading: toTwoFigures(p),
387	    under: toRange(lo, hi),
388	    spoken: `${OWNER_WORDS[owner]}: ${toReading(p, lo, hi)}`,
389	    note,
390	    numeric: true,
391	    step: likelihoodStep(p),
392	  };
393	}
394	
395	/** What a belief chip needs to draw itself. */
396	export interface BeliefChipProps {
397	  /** Whose number this is. There are three, and they are never averaged. */
398	  readonly owner: BeliefOwner;
399	  /** The number, or the absence that stands where it would have been. */
400	  readonly slot: Known<Ranged>;
401	  /** A word shown instead of a likelihood, when the claim stands on the reader's say-so. */
402	  readonly standing?: Standing;
403	  /**
404	   * How many versions of the map were run to produce this number.
405	   *
406	   * Absent means nothing computed it, and the model chip then says so rather
407	   * than describing a run that never happened.
408	   */
409	  readonly versions?: number;
410	}
411	
412	/** One of the three belief chips on a tile. */
413	export function BeliefChip({ owner, slot, standing, versions }: BeliefChipProps) {
414	  const noteId = useId();
415	  const [pinned, setPinned] = useState(false);
416	  const { reading, under, spoken, note, numeric, step } = readChip(owner, slot, standing, versions);
417	
418	  return (
419	    <span className="belief-chip" data-owner={owner} data-reading={numeric ? "number" : "words"}>
420	      {/* The face of the chip is the thing you can reach, so that looking at it
421	          with a pointer and arriving at it with the keyboard do the same thing.
422	          Pressing it pins the note open, for a reader who wants both hands free
423	          while they read it; pressing again puts it away. It is named by the
424	          whole reading — the number and its range together — because that is how
425	          the chip would be said out loud, and the range is never left off. */}
426	      <button
427	        className="belief-chip__face"
428	        type="button"
429	        aria-label={spoken}
430	        aria-describedby={noteId}
431	        aria-controls={noteId}
432	        aria-expanded={pinned}
433	        onClick={() => setPinned((was) => !was)}
434	      >
435	        <span className="belief-chip__owner">{OWNER_WORDS[owner]}</span>
436	        <span className="belief-chip__reading">
437	          {/* The bounded bar the likelihood rides on: one of five brightnesses,
438	              the same size whatever the number is. Brightness is the whole of
439	              what it says and the number printed beside it is the reading, so
440	              the bar only has to clear three to one while the number clears four
441	              and a half. It is drawn on the chip, never over a whole tile:
442	              tile-wide brightness is already spent on the other world in a diff
443	              and on the hover lens, and three meanings on one channel means none
444	              of them reads. */}
445	          {step === null ? null : (
446	            <span className="belief-chip__bar" data-step={step} aria-hidden="true" />
447	          )}
448	          <span className="belief-chip__figure">{reading}</span>
449	        </span>
450	        <span className="belief-chip__under">{under ?? ""}</span>
451	      </button>
452	      <span className="belief-chip__note" id={noteId} data-pinned={pinned ? "yes" : "no"}>
453	        <span className="belief-chip__note-label">{note.label}</span>
454	        <span className="belief-chip__note-sentence">{note.sentence}</span>
455	      </span>
456	    </span>
457	  );
458	}
