content.content:
1	/**
2	 * Where the browser's reading of an edit and the engine's must agree.
3	 *
4	 * Two things read the same branch. The browser walks the arrows and says what
5	 * an edit **can reach**; the engine works every likelihood through and says what
6	 * **moved**. They answer different questions, so they are not the same list —
7	 * and where they *can* be compared they must agree, because a browser quietly
8	 * disagreeing with the engine about what an edit reached is the traceability
9	 * rule broken in the one place nobody would look.
10	 *
11	 * **The engine is the authority.** This file does not repair either reading and
12	 * does not prefer one: it hands back every place the two contradict each other,
13	 * in plain words, so that a test can fail with the claim named.
14	 *
15	 * Two rules, and they are the same rule read in both directions.
16	 *
17	 * | The browser says | The engine says | Verdict |
18	 * |---|---|---|
19	 * | your edit cannot reach this | it moved | a contradiction |
20	 * | your edit cannot reach this | it arrived with the edit | a contradiction |
21	 * | your edit can reach this | it arrived with the edit | a contradiction |
22	 * | your edit can reach this | it did not move | agreement — reachable is not moved |
23	 * | your edit cannot reach this | it did not move | agreement |
24	 *
25	 * The middle row is the one worth spelling out: a claim your edit can reach
26	 * whose number happened to hold still is **not** a claim your edit cannot reach,
27	 * so *reachable* and *unchanged* together are no contradiction at all.
28	 *
29	 * This file does no arithmetic and reads no likelihood. It compares words.
30	 */
31	
32	import type { DiffState } from "../../world/types";
33	
34	/** One of the four words the engine uses for what happened to a claim. */
35	export type EngineState = "unchanged" | "shifted" | "added" | "killed";
36	
37	/** What each of the engine's words means, in the reader's own. */
38	const ENGINE_IN_WORDS: Record<EngineState, string> = {
39	  unchanged: "it did not move",
40	  shifted: "it moved",
41	  added: "it arrived with the edit",
42	  killed: "it was supposed false",
43	};
44	
45	/** What each of the browser's words means, in the reader's own. */
46	const BROWSER_IN_WORDS: Record<DiffState, string> = {
47	  untouched: "an edit cannot reach this claim",
48	  downstream: "your edit can reach this",
49	  added: "it arrived with the edit",
50	  killed: "it was supposed false",
51	  shifted: "it moved",
52	};
53	
54	/**
55	 * Is what the browser said and what the engine said about one claim a
56	 * contradiction?
57	 *
58	 * @param browser The word the browser worked out from the branch alone.
59	 * @param engine The word the engine worked out from the numbers.
60	 */
61	function contradicts(browser: DiffState, engine: EngineState): boolean {
62	  if (browser === "untouched") {
63	    // An edit changes only what is still joined to its subject. So a claim
64	    // outside its reach cannot have moved and cannot have arrived with it.
65	    return engine !== "unchanged";
66	  }
67	  if (browser === "added") {
68	    return engine !== "added";
69	  }
70	  if (browser === "killed") {
71	    return engine !== "killed";
72	  }
73	  // The browser said the edit can reach this claim. Whether it moved is the
74	  // engine's to say — both answers are consistent with being reachable — but a
75	  // claim that arrived with the edit should have been spotted as `added`.
76	  return engine === "added";
77	}
78	
79	/**
80	 * Every place the browser's reading and the engine's contradict each other.
81	 *
