/**
 * How this product writes a day: `Oct 1`.
 *
 * Read in the map's own reckoning rather than in the reader's time zone,
 * because a claim settled on the first of November is settled on the first of
 * November wherever the reader happens to be sitting — and because a supposition
 * dated by the reader's clock would make the same map read differently in two
 * places.
 */

/**
 * Print a day the way the map prints one.
 *
 * @param isoDate A day as the server writes one: `2026-10-01`.
 * @returns The day in words, such as `Oct 1`. A day it cannot read comes back
 *   exactly as it arrived, rather than as a guess.
 */
export function toDay(isoDate: string): string {
  const parsed = new Date(`${isoDate}T00:00:00Z`);
  if (Number.isNaN(parsed.getTime())) {
    return isoDate;
  }
  return new Intl.DateTimeFormat("en", {
    month: "short",
    day: "numeric",
    timeZone: "UTC",
  }).format(parsed);
}

/**
 * How many whole days there are from one day to another.
 *
 * Used to find a claim's own resolve-by day among the days a world was worked
 * through, so that the number on a tile and the word beside it are read on the
 * same day. Both days are read in the map's own reckoning, never the reader's
 * time zone, so the answer is the same wherever the page is open.
 *
 * This is arithmetic on days and never on likelihoods. Counting days is
 * calendar work; a number on the map is only ever read, never combined.
 *
 * @param from The earlier day, as the server writes one: `2026-10-01`.
 * @param to The later day, written the same way.
 * @returns The count of days between them, or nothing at all when either day
 *   cannot be read — because a guessed day would put a tile's number on the
 *   wrong day, which is worse than saying there is none.
 */
export function daysApart(from: string, to: string): number | null {
  const first = new Date(`${from}T00:00:00Z`).getTime();
  const second = new Date(`${to}T00:00:00Z`).getTime();
  if (Number.isNaN(first) || Number.isNaN(second)) {
    return null;
  }
  const oneDay = 24 * 60 * 60 * 1000;
  return Math.round((second - first) / oneDay);
}

/**
 * A claim's own words, ready to be quoted inside a sentence.
 *
 * Two changes and no others. The full stop at the end goes, because the quote
 * sits inside a line rather than ending one. And an article at the front — *A*,
 * *An*, *The* — is lowercased, because that is the one word whose capital letter
 * belongs to the claim's own sentence rather than to the words themselves.
 * Everything else keeps the case the map gave it, so *Brent*, *OPEC+* and
 * *Hormuz* stay as they are.
 *
 * @param claim The claim in the map's own words.
 */
export function asQuoted(claim: string): string {
  const withoutStop = claim.replace(/\.$/, "");
  const [first = "", ...rest] = withoutStop.split(" ");
  if (["A", "An", "The"].includes(first)) {
    return [first.toLowerCase(), ...rest].join(" ");
  }
  return withoutStop;
}

        Every line above is a number something else worked out: the starting number and each push
        are on the map, and the result is the engine's. Nothing on this panel adds them up — two
        things that work out one number eventually disagree about it, and then nobody can say which
        is right.
      </p>
    </Section>
  );
}

/**
 * What this edit did to this claim's number, when the engine says it did
 * anything.
 *
 * Both readings are the engine's, and which way it went is the engine's word:
 * this panel prints them and subtracts nothing. Beside them goes the share of
 * the versions of the map that moved the same way, headed in the reader's own
 * words rather than by the field's name.
 */
function WhatYourEditDid({ claim }: { claim: ClaimView }) {
  const moved = claim.moved;
  // A claim whose value an edit fixed has no move to report: it is true — or
  // false — in every version of the map, and the badge that says so is the
  // whole of what happened to it.
  if (moved === undefined || claim.standing !== undefined) {
    return null;
  }
  const agreed = moved.sameDirection.reading;
  // The engine's verdict on the claim, which is not the same thing as the two
  // numbers: a claim can move a hair and still come out unchanged.
  const counted = claim.diff === "shifted";
  // A claim that moved only by reweighting is a third case, and the two
  // sentences below would both be false of it: the versions did not disagree
  // about a direction, because not one version that counts moved at all. The
  // sentence that *is* true of it is printed at the head of the decomposition,
  // where the chapter puts it.
  const reweighted = moved.onlyReweighted === true;

  return (
    <Section title="What your edit did">
      <p className="inspector__moved">
        <span className="inspector__mono">
          {toMovement(moved.from, moved.to, moved.by, moved.way)}
        </span>
        <span className="inspector__moved-word">{counted ? moved.way : "no change"}</span>
      </p>
      {counted || reweighted ? null : (
        <p className="inspector__reason">
          The engine compared the two worlds and reports no change on this claim: a move counts only
          when the versions of the map agree on which way it went, and these did not.
        </p>
      )}
      {reweighted ? null : (
        <>
          <dl className="inspector__pairs">
            <dt>same direction</dt>
            <dd>
              {agreed === undefined ? (
                moved.sameDirection.absence.words
              ) : (
                <span className="inspector__mono">{toShare(agreed)}</span>
              )}
            </dd>
          </dl>
          <p className="inspector__reason">
            {agreed === undefined
              ? moved.sameDirection.absence.reason
              : "The share of the versions of the map — each one a set of numbers this model " +
                "would have stood behind — in which this claim moved the same way. It is a " +
                "column beside the move and never multiplied into it."}
          </p>
        </>
      )}
    </Section>
  );
}

/** A claim, top to bottom. */
function ClaimDetail({ world, claim }: { world: WorldView; claim: ClaimView }) {
  const baseRate = claim.baseRate;

  return (
    <>
      <header className="inspector__head">
        <p className="inspector__claim">{claim.claim}</p>
        <p className="inspector__kind">{KIND_WORDS[claim.kind]}</p>
      </header>

      {/* Criteria, the source that adjudicates, and the date — all three, on
          every claim. A claim nobody can score is not a claim. */}
      <Section title="Resolves">
        <p className="inspector__body">{claim.resolutionCriteria}</p>
        <dl className="inspector__pairs">
          <dt>judged by</dt>
          <dd>{claim.resolutionSource}</dd>
          <dt>by</dt>
          <dd className="inspector__mono">{claim.resolvesBy}</dd>
        </dl>
      </Section>

      <Section title="Base rate">
        {"reading" in baseRate ? (
          <>
            <p className="inspector__count">
              <span className="inspector__mono">{`${baseRate.reading.k} of ${baseRate.reading.n}`}</span>
            </p>
            <p className="inspector__body">{baseRate.reading.referenceClass}</p>
            {baseRate.reading.sources.length === 0 ? (
              <p className="inspector__reason">
                Nobody has checked this count, so nothing downstream of it may call itself
                documented.
              </p>
            ) : (
              <ul className="inspector__sources">
                {baseRate.reading.sources.map((item) => (
                  <li key={item.url} className="inspector__source">
                    <span className="inspector__source-host">{item.host}</span>
                  </li>
                ))}
              </ul>
            )}
          </>
        ) : (
          <>
            <p className="inspector__words">{baseRate.absence.words}</p>
            <p className="inspector__reason">{baseRate.absence.reason}</p>
          </>
        )}
      </Section>

      {/* The model's likelihood before this claim's causes are taken into

/**
 * The rail beside the map: the endings your edit can reach.
 *
 * An **ending** is where an argument turns into a position — a claim that names
 * something you could trade, or one that names why there is nothing to trade.
 * The rail lists the ones this edit can reach and, beside each, three things:
 * how far its number moved, **how firm** that number is, and whether it went the
 * **same direction** whatever numbers the map started from.
 *
 * **The rail ranks nothing.** When the engine has ordered these rows — largest
 * move along the best-backed route first — the rail draws them in that order and
 * says so. When nothing has, it lists them in the order the map stores them and
 * says *that*, because map order is visibly arbitrary while an invented ranking
 * looks like an answer, and a ranking is the one thing the rail exists to tell
 * you.
 *
 * **An ending that did not move still gets a row.** The engine lists the ones
 * that moved; an ending missing from that list could mean either "it held still"
 * or "it is not on this map", and silence cannot be told from absence. So the
 * unmoved ones follow the ranked ones, reading *no change*, never mixed in among
 * them.
 *
 * The two columns are never folded into any ordering. They answer different
 * questions and a trader weighs them separately; folding the width into a rank
 * would sink exactly the claims that most deserve a second look.
 */

import { useId, useState } from "react";
import type { DeltaRow, Known } from "../world";
import { toMovement, toShare, toSize } from "./BeliefChip";
import "./deltaRail.css";

/** What the rail needs to draw itself. */
export interface DeltaRailProps {
  /** The endings this edit can reach, in whatever order they arrived in. */
  readonly rows: readonly DeltaRow[];
  /**
   * Whether something has put these rows in an order that means something.
   *
   * True once the engine has ranked them. False before that, and the rail says
   * so out loud rather than letting map order be mistaken for a ranking.
   */
  readonly ranked: boolean;
  /** The one line saying what this edit did to the trades, or the reason there is none. */
  readonly summary: Known<string>;
}

/** What each kind of ending is, in a word. */
const KIND_WORDS: Record<string, string> = {
  market: "tradeable",
  not_tradeable: "not tradeable",
  event: "event",
  hypothesis: "hypothesis",
};

/**
 * One cell: the number, or the words standing where it would have been.
 *
 * A cell with no number is a button, because the reason it has no number is a
 * sentence and there is no room for a sentence in a column this narrow. Pressing
 * it prints the sentence under the rail; its accessible name carries the same
 * sentence, so a reader who never sees the rail gets it without pressing
 * anything.
 */
function Cell({
  value,
  onReason,
}: {
  value: Known<string>;
  onReason: (reason: string | null) => void;
}) {
  if (value.reading !== undefined) {
    return <span className="delta-rail__value">{value.reading}</span>;
  }
  const { words, reason } = value.absence;
  return (
    <button
      className="delta-rail__value delta-rail__value--absent"
      type="button"
      aria-label={`${words}. ${reason}`}
      onClick={() => onReason(reason)}
      onFocus={() => onReason(reason)}
      onMouseEnter={() => onReason(reason)}
    >
      {words}
    </button>
  );
}

/**
 * The change itself, as one cell reads it: `.50 ▼ .42`, and the day the two
 * worlds were furthest apart.
 *
 * A row is read on the **day of largest divergence** rather than on the claim's
 * own judging day, because a change that shows up for a fortnight and then
 * unwinds is the thing a trader acts on — so the row names that day.
 */
function changeOf(row: DeltaRow): Known<string> {
  const move = row.move.reading;
  if (move === undefined) {
    return { absence: row.move.absence };
  }
  return { reading: toMovement(move.from, move.to, move.by, move.way) };
}

/**
 * How firm the new number is: the width of its own range.
 *
 * A width is a **size**, not a likelihood: it is how far apart the two ends of a
 * band sit. So it takes no certainty guard — a band four thousandths wide is a
 * remarkably firm number and the reader wants to see it, where `<.01` would say
 * only that it is small.
 */
function firmnessOf(row: DeltaRow): Known<string> {
  return row.rangeWidth.reading === undefined
    ? { absence: row.rangeWidth.absence }
    : { reading: toSize(row.rangeWidth.reading) };
}

/** The share of versions of the map that moved the same way, as a whole percentage. */
function sameDirectionOf(row: DeltaRow): Known<string> {
  return row.agreement.reading === undefined
    ? { absence: row.agreement.absence }
    : { reading: toShare(row.agreement.reading) };
}

/** The rail beside the map. */
export function DeltaRail({ rows, ranked, summary }: DeltaRailProps) {
  const [reason, setReason] = useState<string | null>(null);
  const headingId = useId();

  return (
    <section className="delta-rail" aria-labelledby={headingId}>
      <h2 className="delta-rail__heading" id={headingId}>
        Where this edit ends up
      </h2>

      {/* The one line saying what the edit did to the trades. The engine writes
          it from a fixed template with its own numbers in the blanks; before it
          has, the slot says why there is none. */}
      <p className="delta-rail__summary">
        {summary.reading ?? summary.absence.words}
        {summary.reading === undefined ? (
          <span className="delta-rail__summary-reason">{summary.absence.reason}</span>
        ) : null}
      </p>

      {rows.length === 0 ? (
        <p className="delta-rail__empty">
          No ending on this map is reachable from your edits yet. Make one — press E on a claim —
          and the endings it can reach are listed here.
        </p>
      ) : (
        <>
          <p className="delta-rail__order">
            {ranked
              ? "In the order the engine put them in: the size of the move times the weakest arrow on the best-backed route behind it. Endings that did not move follow, and are not ranked."
              : "In map order. Nothing has ranked these, because nothing has worked out a number to rank them by."}
          </p>

          <div className="delta-rail__table">
            <div className="delta-rail__labels" aria-hidden="true">
              <span>change</span>
              <span>how firm</span>
              <span>same direction</span>
            </div>
            <ul className="delta-rail__rows">
              {rows.map((row) => (
                <li
                  className="delta-rail__row"
                  key={row.claimId}
                  data-moved={row.noChange === true ? "no" : "yes"}
                >
                  <p className="delta-rail__label">
                    <span className="delta-rail__id">{row.claimId}</span>
                    {row.label}
                    <span className="delta-rail__kind">{KIND_WORDS[row.kind] ?? row.kind}</span>
                    {row.move.reading === undefined ? null : (
                      <span className="delta-rail__day">
                        {`${row.move.reading.way} · largest on ${row.move.reading.largestOn}`}
                      </span>
                    )}
                  </p>
                  <div className="delta-rail__values">
                    <Cell value={changeOf(row)} onReason={setReason} />
                    <Cell value={firmnessOf(row)} onReason={setReason} />
                    <Cell value={sameDirectionOf(row)} onReason={setReason} />
                  </div>
                </li>
              ))}
            </ul>
          </div>

          <p className="delta-rail__reason">
            {reason ??
              "Every reading above is the engine's own, in the engine's own order. Reach one with " +
                "the keyboard, or point at it, and whatever it has to say is printed here."}
          </p>
        </>
      )}
    </section>
  );
}

